var ZG_DM_CATS=["子","天文类","丑","地舆类","寅","伦常类","卯","人事类","辰","形体类","巳","释道类","午","动植类","未","服饰类","申","居处类"],ZG_DM_SETS=[[1,"梦天","梦天","主清贵之象。"],[1,"梦天","梦上天","\uFF08一\uFF09积善者主获天佑。\uFF08二\uFF09作恶之人,梦此有降祸之兆。"],[1,"梦天","梦捧天","主建功立业之兆。"],[1,"梦天","梦天压身","有饿死奇祸。"],[1,"梦天","梦天破","凡百忧虑,上危中,主有大丧大败。若梦以木撑破天,更不宜妄动。"],[1,"梦天","梦竖木天上","木竖天为“未”字,一切事尚无成就之望。"],[1,"梦天","梦补天",'\uFF08一\uFF09文人主贵。\uFF08二\uFF09妇人主克夫再醮\uFF08再醮:古代男女婚嫁时,父母为之举行酌酒仪式曰“醮”,男再娶,女再嫁则皆称为"再醮",后专指妇女再嫁。\uFF09'],[1,"梦天","梦天近身","主得荣宠。"],[1,"梦天","梦仰卧视天","为身倚实地,得见天日之兆,大吉。"],[1,"梦天","梦天地分","有上下隔绝之兆。\uFF08一\uFF09平民梦之,父母、夫妻、主仆分离散失。\uFF08二\uFF09贵人梦之吉。"],[1,"梦天","梦天地合","主交泰之象,父母安宁夫妇和谐,谋无不遂、求无不利。"],[1,"梦天","梦天地转","作事求谋,均有改业迁图之兆。"],[1,"梦天","梦天悲鸣","主凶丧大故,到处兵荒。"],[1,"梦天","梦天将晓","有年华方盛之象。"],[1,"梦天","梦满天放彩","主富贵胜常,梦此大吉。"],[1,"梦天","梦天晚天光","主家道中落,晚景凄凉。"],[1,"梦天","梦天昏黑","主作事不明,情意郁抑。"],[1,"梦天","梦天色黑白","主不祥之兆。"],[1,"梦天","梦天色红黄","主运行水土,福禄永昌。若见天门红赤,则主刀兵。"],[1,"梦日月","梦见日月","主开明之象,大吉。"],[1,"梦日月","梦云开见日","此梦为妻得夫、讼有理、商获利、口舌散、疾病除。"],[1,"梦日月","梦捧日","有大贵之象。"],[1,"梦日月","梦载日","梦此必然骤贵。"],[1,"梦日月","梦授日","主得贵子。"],[1,"梦日月","梦抱日","亦主大贵,必得光荣。"],[1,"梦日月","梦吞日","亦主生贵子。"],[1,"梦日月","梦与日斗","病人梦之,主病将愈。"],[1,"梦日月","梦骑日","\uFF08一\uFF09贵人梦之,大吉大利。\uFF08二\uFF09常人梦之,主得心火身热之病。\uFF08三\uFF09老人梦之在为不祥。"],[1,"梦日月","梦双日照户","主贵人联车至,喜气重重,福禄绵绵,孕者主双生贵子。"],[1,"梦日月","梦日光照身","士人荣显,商买获利,女子孕贵。"],[1,"梦日月","梦日出室内","女子得此,亦主得贵子。"],[1,"梦日月","梦负日","主暴贵,亦因是得福。"],[1,"梦日月","梦日初升","此兆位将升,福将至,病将起,子将生,业将兴,寿将增,人将至也。"],[1,"梦日月","梦日黑暗","为奸邪欺蔽,诸事不佳之兆。男子忧父母,妇人妨夫主。"],[1,"梦日月","梦月食","病人梦之,有痊愈之象。"],[1,"梦日月","梦抱月","妇人梦之,主得大贵之女。男子梦之,主得贤美之妻。"],[1,"梦日月","梦摸月","此主平地升天飞腾遇贵之象。"],[1,"梦日月","梦玩月","主生存不久之兆。"],[1,"梦日月","梦月暗","\uFF08一\uFF09此为阴中之阴,孕妇梦之吉。\uFF08二\uFF09主母有忧病,妻有灭殃,百事曖昧不明之兆。"],[1,"梦日月","梦月出海中","此为财源兴发、子孙繁盛之兆,主谋望成遂,婚姻必谐,孕育贵子,财利丰收,名誉大起。"],[1,"梦日月","梦月沉水底","此主经商无望,婚姻不就,诸事不吉,功名子嗣尽如水中之月,乃凶象也。"],[1,"梦日月","梦日月生草",'日旁月为"明”，明上草为“萌”。萌发,盛之象也、主田土丰熟,家宅安宁,营谋称遂,子嗣昌盛。'],[1,"梦日月","梦日月光照身","主夫荣子贵,大吉大利。"],[1,"梦星斗","梦吞星","梦此当生仙子。"],[1,"梦星斗","梦见妖星","主非吉兆,禳之可免。"],[1,"梦星斗","梦星行动","\uFF08一\uFF09常人梦之,有改旧图新之象。求利须转方,求名须游学。官讼别诉,疾病宜禳。孕防堕,婚不成,行人归,音信至。\uFF08二\uFF09闺女梦之,主有谋至。\uFF08三\uFF09寡妇梦之,主有子女前来探访。"],[1,"梦星斗","梦见金星","主有刀兵之兆。"],[1,"梦星斗","梦见文昌星","兆主文明,女人梦此,夫荣子贵。大吉也。"],[1,"梦星斗","梦流星不落","此兆主应迁移,病人有救,远行未归,怀孕未产,求利虚浮。"],[1,"梦星斗","梦北斗昏暗","名高不显,意思忧疑。梦主者,诸须谨慎,妇难孕育,寿难延长,必祈禳以回福。"],[1,"梦星斗","梦手执星","此主女配贵夫,仆投明主,又兼寿命之兆。"],[1,"梦风云","梦忽起大风","主扫荡邪秽。吹嘘德惠之象。"],[1,"梦风云","梦风舟行","主有好人扶助之象,名成利就,讼胜谋遂,百事可望如意。"],[1,"梦风云","梦狂风暴雨","主百事阻碍,营谋无望,有流离颠沛之象。"],[1,"梦风云","梦风摇楼屋欲倒","\uFF08一\uFF09主有移家之兆。\uFF08二\uFF09主门户无人支撑。"],[1,"梦风云","梦乘云","主生子贤明。"],[1,"梦风云","梦红黄云从地起","主禄位起迁,家业兴隆,贸易顺利,子嗣昌吉。"],[1,"梦风云","梦黑云从地起","\uFF08一\uFF09黑主阴气,为瘟疫流行之象。\uFF08二\uFF09主失人之兆。"],[1,"梦风云","梦青云起足下","主商买得利,有远行事,驿马星动。"],[1,"梦风云","梦吞五色云","主生才子,学问聪明。"],[1,"梦风云","梦乘云至佛国","有将死之兆。倘系释家,当入乐界。"],[1,"梦雨露","梦阴雨","阴雨为忧疑沈晦之象,贵贱怀愁,男女多悔,凡事须小心谨慎,以求趋吉。"],[1,"梦雨露","梦求雨","\uFF08一\uFF09女子梦之,婚姻可成;男子梦之,主守孤独。"],[1,"梦雨露","梦细雨","此梦主凡事不成,官事少吉,疾病不愈,经营不遂,行人不至,禄位不临,口舌不明,出行不利。"],[1,"梦雨露","梦雨水泛中庭","\uFF08一\uFF09主诸事丰殷,为吉祥之兆。\uFF08二\uFF09主经商大得财利。"],[1,"梦雨露","梦大雨淋身","有沾恩被泽之兆,文人主官位迁升,商买主财利丰收,争讼遇贵人作主。惟出行与疾病非大吉则大凶,当因人而论。"],[1,"梦雨露","梦迎娶遇雨","此梦为吉祥之兆,夫妻必得偕老,父子必然承欢,兄弟必同扶助,大利也。"],[1,"梦雨露","梦行路遇雨","梦此者,主有酒食宴乐之兆。若遇雨不行,隔一日必验。"],[1,"梦雨露","梦降赤雨","\uFF08一\uFF09所如辄阻,行人遇难。\uFF08二\uFF09主有刀兵血光之灾,家人离散之象。"],[1,"梦雨露","梦大雨如注","\uFF08一\uFF09为阴盛阳孤之象,老年梦之,主损小口,小者梦之,恐丧高年。"],[1,"梦雨露","梦露垂巾帽","\uFF08一\uFF09理财求贵,主有贵人提拔,自渐亨通。\uFF08二\uFF09病人梦之,慎防孝服临身。\uFF08三\uFF09经商远行,乘舟履险,恐遭不测。"],[1,"梦雨露","梦吸露水","此梦有沾受膏泽之兆,病人主得妙药,下人主遇恩泽。"],[1,"梦雨露","梦露水湿衣","兆吉祥也。行路得酒食,婚姻得佳偶,商买得财利,诸凡如意,喜庆异常。"],[1,"梦霜雪","梦身卧雪地","\uFF08一\uFF09主出游,行踪不定。\uFF08二\uFF09主丧母,破产。"],[1,"梦霜雪","梦露成霜霜又成雪","灾祸迭至苦上加苦,君子梦之,须忍小辱,捐小忿,凡事须慎之於微。"],[1,"梦霜雪","梦霜露降","士人梦之,宠临禄至,常人梦之,贵助贤扶,佳祥兆也。"],[1,"梦霜雪","梦踏霜早行","主遇事坎坷,谋为艰难之兆,慎之斯亨。"],[1,"梦霜雪","梦雪消","\uFF08一\uFF09主少烦恼。\uFF08二\uFF09病人梦之,勿药自愈。"],[1,"梦霜雪","梦雪成珠","主有小财至,又防有小忧来。"],[1,"梦霜雪","梦雪人","此主阴柔之象,切宜小心谨慎,以防灾殃。"],[1,"梦霜雪","梦春雪不积","主晴。"],[1,"梦霜雪","梦夏雪","主父母凶丧。"],[1,"梦霜雪","梦夏雪堆积","亦主孝服。"],[1,"梦霜雪","梦夏雪扫去","一切凶事,可望散去。"],[1,"梦霜雪","梦秋雪飘","主多忧愁。"],[1,"梦霜雪","梦秋雪沾衣","当有凶恙。"],[1,"梦霜雪","梦秋雪堆积","主有丧事。"],[1,"梦霜雪","梦冬雪","大吉。"],[1,"梦霜雪","春分梦雪","主有友人来。"],[1,"梦霜雪","雪片大如手掌者","定有凶服。"],[1,"梦霜雪","秋分梦雪堆积","主事业淡泊。"],[1,"梦霜雪","夏至梦消融雪","主一切恶事消散。"],[1,"梦霜雪","冬至梦雪飞空","主有酒客至。"],[1,"梦霜雪","梦下大雪","此为大不祥之兆,主父母下世、兄弟分离、夫妻丧偶、子嗣遭殃,务须禳解。"],[1,"梦霜雪","梦行丧遇雪","\uFF08一\uFF09兆主重丧,大不祥也。\uFF08二\uFF09贵人梦之,主赴官被泽转为吉利。"],[1,"梦霜雪","梦山上堆雪","\uFF08一\uFF09为积忧聚闷之象,有父母者,恐有忧服。\uFF08二\uFF09商买梦之,主大获财利。"],[1,"梦霜雪","梦担雪送人","担雪献友,庆贺之兆,若梦人送己,尤为大吉。"],[1,"梦霜雪","梦雪飘","\uFF08一\uFF09主疾病祛除,讼事和息,忧消烦解。\uFF08二\uFF09商人梦之,不能聚财,谋事者梦之,不能遂愿。"],[1,"梦霜雪","梦庭中积雪","\uFF08一\uFF09主有凶丧,孝服临身,禳解之吉。\uFF08二\uFF09占作事有始无终。"],[1,"梦霜雪","梦冒雪归","梦此有初因终亨之兆。"],[1,"梦霞雾","梦霞起","霞起为飞升之兆,梦此者必能成名,升官获利,婚姻必谐,争讼得直,疾病无忧,六甲生男,大吉大利。"],[1,"梦霞雾","梦霞照衣","主有大喜庆事,谋望有成,作事顺利,贵人接引,良友扶助,乃衣锦荣身之象也。"],[1,"梦霞雾","梦布化雾","主有威权。"],[1,"梦霞雾","梦黑雾迷身","主有灾眚,作事亦主阻隔难成,行军亦见大败。"],[1,"梦霞雾","梦雾迷宫室","此为烟绕屋宇之兆,家门恐有火灾,急须修禳作善,庶可转祸为福。"],[1,"梦虹霓","梦吞虹霓","孕妇主产佳儿,文人主能得志,壮士有战阵之威。"],[1,"梦虹霓","梦虹起天边","主见干戈,家园扰乱而不宁。"],[1,"梦虹霓","梦绛虹","\uFF08一\uFF09女夺男权,阴操阳柄,室家必紊乱不正。\uFF08二\uFF09主荒歉之象。\uFF08三\uFF09恐有私淫之祸。"],[1,"梦雷电\uFF08雹附\uFF09","梦巨雷击头","梦此者大不祥,求名不利,患病不愈,行人被阻,出行受欺,经商遇盗,亟宜修省,以解禳之。"],[1,"梦雷电\uFF08雹附\uFF09","梦闻雷声","主名利双收,业兴誉至。"],[1,"梦雷电\uFF08雹附\uFF09","梦雷电绕身","\uFF08一\uFF09孕妇梦之,主生贵子。\uFF08二\uFF09士人梦之,主禄位将至。\uFF08三\uFF09婢仆梦之,主家长显达。"],[1,"梦雷电\uFF08雹附\uFF09","梦电光夺目","亦主得贵子。"],[1,"梦雷电\uFF08雹附\uFF09","梦被雷击","\uFF08一\uFF09君子梦之,主得贵人助力。\uFF08二\uFF09小人梦之,则为殃咎,切戒妄贪。"],[1,"梦雷电\uFF08雹附\uFF09","梦雹","\uFF08一\uFF09农人梦此,必获大利。\uFF08二\uFF09亦主禾稼受伤。\uFF08三\uFF09常人梦此,主有母丧,否则死女。诸事恐有损伤,非修德不足以转移之。"],[2,"梦大地","梦得地","主葬亲有佳地。"],[2,"梦大地","梦地动","\uFF08一\uFF09主迁居移业,去旧图新,经商生意发动,尤利坤方。女子主有悔吝。\uFF08二\uFF09常人当得酒食。"],[2,"梦大地","梦见地平广","梦此者,主富厚禄泽,通达安稳,乃大吉之占也。"],[2,"梦大地","梦地裂","是为分崩之兆,主宫府疾病,常人家业衰替,人口不宁,兄弟分居,母妻有变,诸事不利,慎之为是。"],[2,"梦大地","梦地转","主命运亨通。"],[2,"梦大地","梦地高近天","有以下陵上之象,切戒。"],[2,"梦大地","梦地陷","南方陷无咎,东西陷俱不祥,北方陷沈顿,中央陷受困。须视其方位,以定诸事之吉凶。"],[2,"梦大地","梦地变高","主家业兴隆。"],[2,"梦大地","梦己转地","主功成名立。"],[2,"梦大地","梦地膏腴","主得福泽。"],[2,"梦大地","梦地倾侧","是为兵荒之象。"],[2,"梦大地","梦地低下","主家业将落。"],[2,"梦大地","梦云起地下","云黄红者吉,黑白者凶。"],[2,"梦山水","梦山开","主为利益之祥,亨通之兆。"],[2,"梦山水","梦开山","\uFF08一\uFF09禅家梦之,主能成佛。\uFF08二\uFF09常人梦之,主为殡葬之占。"],[2,"梦山水","梦山上挂丝","山挂丝为幽字。妇人梦之,主为幽郁。贵人梦之,主幽囚不吉。"],[2,"梦山水","梦上山欲堕","主转败为胜,得人来助。望。"],[2,"梦山水","梦走马上山","\uFF08一\uFF09此为先难后易之兆,仕宦从险中禄马高擢,商买从险处获利盈馀。\uFF08二\uFF09人上山为凶字,主有杀身之祸。"],[2,"梦山水","梦山行","凡梦此者,主握大权,获大利,亨大福,富贵吉祥,美不可言。被围者可出围。"],[2,"梦山水","梦山上流泉","山上有水,利西南不利东北。其道穷也,主生出死归。"],[2,"梦山水","梦上山读书","\uFF08一\uFF09文人主得誉扬。\uFF08二\uFF09囚人梦之,有出狱之望。"],[2,"梦山水","梦山林中行","\uFF08一\uFF09此梦商买大吉,有茂盛祯祥,年丰兴旺之象。\uFF08二\uFF09人配山为仙,配木为休,故梦行山中吉,梦行林中凶。"],[2,"梦山水","梦水边一女","水边女为汝字,宜往以汝字为名地方。"],[2,"梦山水","梦水澄清","梦之者,主由贫而富,由贱而贵,气运亨通,诸事吉祥。"],[2,"梦山水","梦水浑黑","主有阴私之事。"],[2,"梦山水","梦洪水","\uFF08一\uFF09注营谋成遂,财利充盈。\uFF08二\uFF09疾病主虚,讼狱主惊;家临江海者,须防水灾。\uFF08三\uFF09主有寇盗兵戈之征。"],[2,"梦山水","梦水干涸","主事业已穷。"],[2,"梦山水","梦水斗","主财产耗散。"],[2,"梦山水","入水捉蛇","巳年月日梦此,常人主得财利,文人当得功名。非达己不应。"],[2,"梦山水","梦饮水不止","饮不止,利无穷。水为利,饮为通。商买梦之,大吉大利。"],[2,"梦山水","梦水啸","主饱受虚惊。"],[2,"梦山水","梦水中有岸","水中岸谓之洲,洲与州通。梦此者利往某州,如杭州、苏州、荆州。行商尤吉。"],[2,"梦山水","梦身在浴水中","\uFF08一\uFF09有除旧布新之兆,主名成利遂,诸事俱吉。\uFF08二\uFF09经商须慎,远行防有不测。"],[2,"梦山水","梦水发赤","主以下凌上之象。"],[2,"梦山水","梦流水绕身","主争讼入狱,患病不治,或是脓血,船家梦之，防有覆船之险,非吉祥之兆也。"],[2,"梦山水","梦家中大水","兆主财旺业盛,喜占添丁。"],[2,"梦土石","梦取土","主於无意之中,横得财利,谋望有成,迁移大吉,行路拾得遗物,婚娶能得妻财。"],[2,"梦土石","梦运土石人家","土厚重主富,石峻大主贵,运入家中,富贵可必。"],[2,"梦土石","梦行土堆上","土堆为坟墓之象,梦此者主病不愈,诸事不利,亟宜修省。"],[2,"梦土石","梦见大石","此梦主富贵齐至,父母得享大年,子孙并皆贤秀。大吉大利。"],[2,"梦土石","梦山岩险峻","主营谋不利,诸事阻绝,命运淹蹇,远行经商,更须防陆路山径之险。"],[2,"梦土石","梦遇堕马坡","主三日后乘马颠蹶,然得遇名医,毙而复生。"],[2,"梦土石","梦大石入家","\uFF08一\uFF09主有大贵人至。\uFF08二\uFF09营谋必获大利,家业必能增进,乃喜庆佳祥之兆也。"],[2,"梦土石","梦身在岩石上","梦此者,主官上加官,利中得利,有安如磐石之象。"],[2,"梦江海河湖","梦江水大发","此为称心如意之兆,出仕主进取,经商主大获,气运非常亨通。"],[2,"梦江海河湖","梦日升海中","主得横财,发福禄,百事均吉。"],[2,"梦江海河湖","梦河清","此为太平之象。"],[2,"梦江海河湖","梦河水干","河无水为可字,病者梦之,主病必愈。"],[2,"梦江海河湖","梦入河饮水","\uFF08一\uFF09此为逢凶化吉、渴处得浆之兆;病人梦之,大症立愈;士子梦之,临文添思；常人梦之,主有水姓人来求婚姻。凡事均得润泽也。\uFF08二\uFF09孕妇梦之,主生贵子。"],[2,"梦江海河湖","梦大战湖中","\uFF08一\uFF09男子梦之,主获大利。\uFF08二\uFF09女子梦之,主得佳配。"],[2,"梦江海河湖","梦湖中云起","\uFF08一\uFF09此为吉祥之兆。喜中生喜,利外得利。\uFF08二\uFF09妇人梦之,主有喜气。"],[2,"梦江海河湖","梦石泉","主增进诗思。"],[2,"梦冰","梦食冰","\uFF08一\uFF09主谋事徒劳,商买梦之,餐风露宿,不能获利。\uFF08二\uFF09病人梦之,主解烦消热。"],[2,"梦冰","梦水结成冰","有财源结聚之兆,梦之者功名亨利,交易有望，婚姻成就。诸事吉利,佳象也。"],[2,"梦冰","梦敲冰行船","有向前进之象,梦之者,应无往不利。"],[2,"梦冰","梦身卧冰上","此梦主阴消阳陷,争讼防幽羁,患病虞死亡,凶兆也。"],[2,"梦冰","梦与冰雪","主家业消耗之象。"],[2,"梦冰","梦与冰露","主流动不宁之象。"],[2,"梦火\uFF08烟附\uFF09","梦火灭","此梦大为不祥,主家亡财散,疾病不起,讼事陷罪,仕宦罢斥。"],[2,"梦火\uFF08烟附\uFF09","梦门上火起","此梦主诸事闪烁。"],[2,"梦火\uFF08烟附\uFF09","梦取水浇火","此为预防之象,事事务须谨慎,庶可无咎。"],[2,"梦火\uFF08烟附\uFF09","梦邻家火发","延烧己屋者吉,不烧者不利。避邻家火者吉,救邻家火者失威。"],[2,"梦火\uFF08烟附\uFF09","梦行火中","主有病即愈,求名即成,得贵人前来扶持。"],[2,"梦火\uFF08烟附\uFF09","梦屋中火发","主家业兴隆。"],[2,"梦火\uFF08烟附\uFF09","梦身受火烧","大凶,慎之。"],[2,"梦火\uFF08烟附\uFF09","梦火烧己屋","\uFF08一\uFF09主财源兴旺。\uFF08二\uFF09老人梦之,主得心火病。"],[2,"梦火\uFF08烟附\uFF09","梦空中大火","火属阳气。梦此者,主声威日振,家业大兴,行商大获,官司必胜,诸事有大吉之象。"],[2,"梦火\uFF08烟附\uFF09","梦宅中火光明亮","主昌荣吉利。"],[2,"梦火\uFF08烟附\uFF09","梦山上大火","\uFF08一\uFF09仕宦主禄位高迁,商买主贸易兴豪。\uFF08二\uFF09行人梦之,主不即归。"],[2,"梦火\uFF08烟附\uFF09","梦厅角燃火","主官居明府。"],[2,"梦火\uFF08烟附\uFF09","梦火驱车行","主喜庆大来,气运亨通,禄位高迁,家业丰盛。"],[2,"梦火\uFF08烟附\uFF09","梦火光烛","此梦火在天上,梦之者宜遏恶扬善,顺天休命。"],[2,"梦火\uFF08烟附\uFF09","梦看放烟","主百事无忧,病去大吉。"],[2,"梦火\uFF08烟附\uFF09","梦烟起衣上","君子梦之吉,小人梦之凶。"],[2,"梦火\uFF08烟附\uFF09","梦吞烟","主口舌纷争,或疾病临身,或火灾猝至。"],[2,"梦火\uFF08烟附\uFF09","梦烟云四起","梦此者主百事亨通,名利双收。"],[2,"梦火\uFF08烟附\uFF09","梦中发烟","此为家业兴旺之兆,主衣食丰足,富贵吉祥。"],[2,"梦火\uFF08烟附\uFF09","梦烟迷满屋","主奸邪掩闭,或火烧之虞。"],[3,"梦父母\uFF08祖先附\uFF09","梦故父","主不日仙游,不祥之兆也。"],[3,"梦父母\uFF08祖先附\uFF09","梦父为官","在堂主死亡。"],[3,"梦父母\uFF08祖先附\uFF09","梦已故父母复生","主释罪超仙。"],[3,"梦父母\uFF08祖先附\uFF09","梦侍父母疾病","侍在堂者,主父母灾殃;侍已故者,主子孙不利。"],[3,"梦父母\uFF08祖先附\uFF09","梦父母索食","主来日二亲有怒责之事。"],[3,"梦父母\uFF08祖先附\uFF09","梦葬父母","主家园旺盛。"],[3,"梦父母\uFF08祖先附\uFF09","梦见父母葬地","如松柏多者,主后代兴隆。"],[3,"梦父母\uFF08祖先附\uFF09","梦父母来迎","生者迎生,团圆之会。死者迎生,死别生离。"],[3,"梦父母\uFF08祖先附\uFF09","梦父子同坐","贵人主职位并尊,平人主父母康强,子孙贤秀。"],[3,"梦父母\uFF08祖先附\uFF09","梦父母悲泣","主明日家庭有喜宴之事。"],[3,"梦父母\uFF08祖先附\uFF09","梦见祖先","\uFF08一\uFF09主先灵不安,或有所见告。\uFF08二\uFF09妇女梦之,主来日必有闲是闲非,谋为不遂。"],[3,"梦兄弟","梦兄弟登山","山为联芳之象,喜庆佳祥也。"],[3,"梦兄弟","梦兄弟入水","主兄弟不利行商,大凶。"],[3,"梦兄弟","梦兄弟疾病","为手足不安之象。"],[3,"梦兄弟","梦兄弟为神","主飞黄腾达之兆。"],[3,"梦兄弟","梦兄弟与物","主手足合力之兆。"],[3,"梦兄弟","梦兄弟同车","主同时发达。"],[3,"梦兄弟","梦兄弟求衣","有同袍更服之象,但吉凶不一定。"],[3,"梦兄弟","梦兄弟相殴","主骨肉协力。"],[3,"梦兄弟","梦兄弟丧葬","主连举同升。"],[3,"梦师友","梦师友登天","\uFF08一\uFF09应试主吉利。\uFF08三\uFF09疾病主凶殃。\uFF08三\uFF09已亡故者,主情意感通,必有冥佑。"],[3,"梦师友","梦师友丧葬","如被风摄去者,主大吉。"],[3,"梦师友","梦与师友同卧","主情义相笃之象。"],[3,"梦师友","梦师友相笑","主互相投契,彼此为莫逆之交。"],[3,"梦师友","梦友人披发跣足","主其人有杀身之祸。"],[3,"梦丈夫","梦夫为官","夫患病时,梦此不祥。"],[3,"梦丈夫","梦夫为僧","\uFF08一\uFF09主琴瑟和谐。\uFF08二\uFF09主夫交易称心。"],[3,"梦丈夫","梦妻有病","主室家有恙。"],[3,"梦丈夫","梦妻妾成神","主孕育不吉。"],[3,"梦丈夫","梦夫妻索食","主室罄粮绝,夫妻交谪。"],[3,"梦丈夫","梦夫妻同车","主唱随和乐之兆。"],[3,"梦丈夫","梦夫妻相殴","主琴瑟和好。"],[3,"梦子女","梦子女登山","贵人加贵,病人加病。"],[3,"梦子女","梦子女入水","主有夭折之占,惟火木命人,祈禳可转为福。"],[3,"梦子女","梦子为官","家有孕妇,未产之前,梦之大吉。"],[3,"梦子女","梦子女忽死","主病除大利。"],[3,"梦子女","梦子女同车","主得贤子佳婿。"],[3,"梦子女","梦子女索食","主不祥之兆,幼者无妨。"],[3,"梦子女","梦子女相迎","同父母相迎。"],[3,"梦子女","梦子女相别","同父母相别。"],[3,"梦子女","梦子女喜笑","同父母喜笑。"],[3,"梦子女","梦子女悲泣","同父母悲泣。"],[3,"梦子女","梦人赠儿","主为善格天之兆,大吉。"],[3,"梦男女老幼","梦寻丈夫","主丈夫死亡。"],[3,"梦男女老幼","梦与男子相殴骂","主能得人力。"],[3,"梦男女老幼","梦与丈夫入水","主大吉之兆。"],[3,"梦男女老幼","梦男女相邀","主有佳祥喜庆之事。"],[3,"梦男女老幼","梦与女人斗殴","注定失财。"],[3,"梦男女老幼","梦见妇女斗殴","主讼事相辱,多有闲气,或有奸情。"],[3,"梦男女老幼","梦见女人梳妆","梦晚妆者,主事成;晓妆者,主事散。"],[3,"梦男女老幼","梦见老人","主年寿永工,财帛丰盈。"],[3,"梦男女老幼","梦见小儿","主凶多吉少。"],[3,"梦男女老幼","梦身化小儿","中年梦之,主财业消退。老年梦之,主疾病死亡。凡人梦此,速削发为僧以应之,可解。"],[3,"梦男女老幼","梦见矮人","主诸事不成,有虎头蛇尾之象。"],[3,"梦农与商贾","梦农人插秧","\uFF08一\uFF09主子孙繁盛,家业振兴,经商大获,吉兆也。\uFF08二\uFF09文人梦之,主才增学进。"],[3,"梦农与商贾","梦身为商人","远出者梦之,主家事不宁,眷口分离之兆。"],[3,"梦农与商贾","梦己开店","主事业增盛,喜气大来。"],[3,"梦农与商贾","梦己为小贩","主有口舌是非。"],[3,"梦农与商贾","梦行商还家","主骨肉完聚,疾病痊愈,财利进益,诸事大吉。"],[3,"梦农与商贾","梦与客商交易","主灾临疾至,凶。"],[3,"梦农与商贾","梦己为巨商","主家业飘零。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦己为医士","梦为人医病,主解人之厄,又与其人有婚姻之约。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦医士为己治病","主有病得救,无疾灾生。贫人主有所获，文人主有所遇。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦孝人习医","主得业荒芜,才人失慧,非吉占也。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦己为人占卜","主将有远行。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦人为己占卜","主有远客来临。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦求人占卜","主其人有疾病将至,灾祸临身。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦人为己算命","主命运亨通,大吉。"],[3,"梦医卜星相\uFF08阴阳家附\uFF09","梦为人谈命","主其人与己有缘,彼此投契。贵人梦之,主荐拔其人。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦迎娶","此梦主与人有缘。仕宦梦之,为加升禄位之征。常人梦之,有新得良朋之兆。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦女出嫁","主必破家。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦己为媒妁","主与人说合之象。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦妇人受孕","主得财帛。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦妻受孕","主有外私。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦见孕妇","主事必成。"],[4,"梦嫁娶\uFF08孕育附\uFF09","梦抱新生子孙","主得大发。"],[4,"梦起居","梦远游","主能获利。"],[4,"梦起居","梦聚别无常","显者梦之有疾,隐者梦之无防。"],[4,"梦起居","梦人叩首","不论叩请叩谢,均主荣显喜庆。"],[4,"梦起居","梦人来叩祝","亦主吉利。"],[4,"梦起居","梦向人叩首","乃佳祥之兆也。梦之者当万事亨昌,百凡顺遂。"],[4,"梦起居","梦笑","主哭泣悲哀。"],[4,"梦起居","梦叹息","主悔吝怒愤。"],[4,"梦起居","梦叹赏","主获吉利。"],[4,"梦起居","梦哭泣","梦此者转为吉兆。"],[4,"梦起居","梦与人对泣","主有喜乐庆贺事。"],[4,"梦起居","梦涕泪行","主丧亡之兆。"],[4,"梦起居","梦放声大哭","主大吉快乐之象。"],[4,"梦起居","梦哀哀哀三字","主死后方荣之象。"],[4,"梦起居","梦悲哀无泪","主有大凶。"],[4,"梦起居","梦涕泣流血","亦主大凶。"],[4,"梦疾病\uFF08死附\uFF09","梦呕吐","(-)病人梦之,主病即去。\uFF08二\uFF09有患难者,梦之,无妨。\uFF08三\uFF09老年梦之,身体康强。"],[4,"梦疾病\uFF08死附\uFF09","梦生者忽死","文人得官,商人得利,病人得愈,常人得食。"],[4,"梦疾病\uFF08死附\uFF09","梦人来托生","主得妻、得子女。"],[4,"梦疾病\uFF08死附\uFF09","梦死里逃生","主延年益寿,诸事祯祥,囚犯得释,疾病可痊之象。"],[4,"梦疾病\uFF08死附\uFF09","梦人死","\uFF08一\uFF09梦尸骨遍地,主荒乱。\uFF08二\uFF09梦抚抱死尸,主得财利。\uFF08三\uFF09梦婴儿死,主争讼和息,邻里安宁,产母无恙。\uFF08四\uFF09梦亲戚朋友死,吉凶不定。\uFF08五\uFF09梦母亲兄弟死,均主疾病。"],[4,"梦疾病\uFF08死附\uFF09","梦抱死人笑","大凶。"],[4,"梦疾病\uFF08死附\uFF09","梦抱死人哭","大吉。"],[4,"梦疾病\uFF08死附\uFF09","梦见死人饮","主有病至。"],[4,"梦疾病\uFF08死附\uFF09","梦与死人同食","此为吉占。"],[4,"梦疾病\uFF08死附\uFF09","梦见已死之人","主忧郁事至,非吉兆也。"],[4,"梦疾病\uFF08死附\uFF09","梦死人出指","主有喜事。"],[4,"梦疾病\uFF08死附\uFF09","梦死人出血","主得财源。"],[4,"梦丧葬","梦吊丧","\uFF08一\uFF09家庭主孝慈妇女主孕育,失人主获人,经商主得利。\uFF08二\uFF09梦虚无棺椁,主所求不能成遂。"],[4,"梦丧葬","梦行丧","\uFF08一\uFF09主显贵发达,\uFF08二\uFF09商贾梦之,财利散失。"],[4,"梦丧葬","梦妻行丧","有家破人亡之祸。"],[4,"梦丧葬","梦子行丧","同上,大凶。"],[4,"梦丧葬","梦殡葬","主吉利之兆。常人梦之,主立业成家;仕宦梦之,主得超迁。"],[4,"梦丧葬","梦殡葬不见棺椁","主殃祸即至。若有鼓吹亭台者,主家破身亡嗣绝,慎之。"],[4,"梦丧葬","梦改葬","\uFF08一\uFF09由卑徒高者吉,主高迁之象。\uFF08二\uFF09由大移小者凶,主流离之兆。"],[4,"梦恩仇","梦人感恩","吉凶不一,须自问平日行为,有德与否,则不难推定矣。"],[4,"梦恩仇","梦人报冤","概主大凶,务须修德以解禳之。"],[4,"梦斗殴","梦杀死人","主富贵福禄,大吉大利。"],[4,"梦斗殴","梦杀人血污衣","主得财利。"],[4,"梦斗殴","梦自己杀人","中吉,主官位荣临。"],[4,"梦斗殴","梦持刀杀人","主得财利。"],[4,"梦斗殴","梦杀伤不死","有血主吉,无血主凶。"],[4,"梦斗殴","梦见他人杀人","大吉,主有人送物至。"],[4,"梦斗殴","梦见他人互杀","主争财之象。"],[4,"梦斗殴","梦持刀斫人","主失力失财。"],[4,"梦斗殴","梦被人斫","主得势力。"],[4,"梦斗殴","梦与人相击","主有权力。"],[4,"梦斗殴","梦击人","主有威力。"],[4,"梦斗殴","梦被人击","大凶。"],[4,"梦斗殴","梦击人不着","主失去势力。"],[4,"梦斗殴","梦人击不中","主灾祸去除。"],[4,"梦斗殴","梦与人大斗","主凡事吉利,但斗胜者得力,斗败者主凶。"],[4,"梦斗殴","梦家中人相斗","主有分别之兆。"],[4,"梦斗殴","梦与女人斗","主有口舌是非。"],[4,"梦斗殴","梦与小人斗","主有鬼崇事,宜镇压解禳。"],[4,"梦斗殴","梦被人打","主得人力。"],[4,"梦斗殴","梦打人","主自己失力。"],[4,"梦斗殴","梦骂人","主受他人欺侮。"],[4,"梦斗殴","梦骂朋友","主作事屈而不伸。"],[4,"梦斗殴","梦骂妻子","主遗失财物。"],[4,"梦斗殴","梦骂父母妻子","主遗失财物。"],[4,"梦斗殴","梦骂衣服器皿","主夫妻反目。"],[4,"梦斗殴","梦骂亡人鬼崇神佛","主有病患。"],[4,"梦斗殴","梦与人相骂","主己伸彼屈,吉兆也。"],[4,"梦斗殴","梦骂人有人劝解","吉兆也。"],[4,"梦斗殴","梦相骂无人劝解","主得人力。"],[4,"梦刑狱","梦在官用刑","不祥之兆。若梦自缚,尤凶。"],[4,"梦刑狱","梦诉讼","\uFF08一\uFF09正人君子,梦之无咎。\uFF08二\uFF09梦胜者吉,梦败者凶。"],[4,"梦刑狱","梦罪犯解审","大吉。"],[4,"梦刑狱","梦罪犯入人家","主有疾疫灾患。"],[4,"梦刑狱","梦自己犯罪","当占其姓名,以定吉凶。"],[4,"梦刑狱","梦自己犯罪被赦","主灾患消灭,病除忧散。"],[4,"梦刑狱","梦罪人逃去","主其人隐怀叵测。"],[4,"梦刑狱","梦逃不脱","主有祸难消。"],[4,"梦刑狱","梦逃走","主祸解脱,身体安好。"],[4,"梦刑狱","梦手持绳索击人","主劳怨烦恼。"],[4,"梦刑狱","梦被人捆缚","主有疾病。"],[4,"梦刑狱","梦与人同缚","主有大灾,亟须修省,或可逢凶化吉。"],[4,"梦刑狱","梦亲手锁人","主他人被害,可报仇雪恨。"],[4,"梦游战","梦围棋","\uFF08一\uFF09有欲斗之意。\uFF08二\uFF09凡营谋者,主事有变更,无定无成之象。\uFF08三\uFF09主能增进智慧。"],[4,"梦游战","梦赌博","主有争斗之事,赢者主得彩银。"],[4,"梦游战","女子梦秋千","主有酒食宴乐,喜庆欢娱之事。"],[4,"梦游战","梦与人击球","主有争斗,闲是闲非。"],[4,"梦游战","梦见人蹴球","男子梦之,主艺事高强。女子梦之,主有宴饮之喜。"],[4,"梦经史书藉","梦读《周易》","君子梦之,遇难得免。小人梦之,行险必亡。此吉凶消长之理也。"],[4,"梦经史书藉","梦读《周礼》","梦此者,主力求上进之象。"],[4,"梦经史书藉","梦见《毛诗》","梦之者,主通达和平,孝顺父母。"],[4,"梦经史书藉","梦读《书经》","主上知天道,下知物理。"],[4,"梦经史书藉","梦与《诗》《书》","主文才大进之象。"],[4,"梦经史书藉","梦读《礼记》","梦此者,其人必品节详明,德性坚定。"],[4,"梦经史书藉","梦见《春秋》","梦之者,必能主持世教,公天下之是非。"],[4,"梦经史书藉","梦读《孝经》","主生男大贤,生女为孝女,著美当时,流芳百世。"],[4,"梦经史书藉","梦阅国史","善人梦之,主百世流芳。恶人梦之,主万年遗臭。"],[4,"梦经史书藉","梦人与己书","\uFF08一\uFF09此发蒙之象,文人梦之,主益智慧,常人梦之,主长机谋。\uFF08二\uFF09如系杂书,主有人来议事。"],[4,"梦经史书藉","梦书放光","主士子能文,仕宦进录,行商丰殖,妇孕贵子,争讼得直,老人得寿。一切营谋,均属得意。"],[4,"梦经史书藉","梦收买旧书","主重重喜事,商贾应大获,士子定进禄。"],[4,"梦经史书藉","梦书满车","此为亨通之兆。行商主得货财,文人主显前程。凡事只须勉力为之,无不成就。"],[4,"梦经史书藉","梦屋角有书","此梦主履险如夷,居危而安,但不可妄有作为。"],[4,"梦经史书藉","梦楼上读书","\uFF08一\uFF09文人学士,梦之最宜。\uFF08二\uFF09常人及商贾梦之,毫无吉凶。"],[4,"梦经史书藉","梦阅秘书","主须慎言慎行。"],[4,"梦经史书藉","梦城楼上读书","梦之者,须思患预防。能一切谨慎,自然纳福。"],[4,"梦经史书藉","梦修补旧书","士子梦之,主须苦攻;商人梦之,主当谨慎;病人梦之,主在医祷。"],[4,"梦经史书藉","梦见黄纸书","行商梦之,利往秦、晋,必能财源大发。"],[4,"梦经史书藉","梦折信","\uFF08一\uFF09有散而不聚之象。梦之者,须防失脱,谨贸易，疾病危。\uFF08二\uFF09争讼者梦之,官司可解。"],[4,"梦经史书藉","梦封函","吉凶善恶,惟人自召,要以修德为重。"],[5,"梦头面","梦断头","\uFF08一\uFF09主有杀身之祸。\uFF08二\uFF09主得功名。"],[5,"梦头面","梦头上生角","角为刀、用二字。梦用刀头上,大凶之兆,亦主断头。"],[5,"梦头面","梦见头顶","主荣显之象。"],[5,"梦头面","梦见人头顶","凡求名利,及作事谋为,均主大吉。"],[5,"梦头面","梦头有血","主有得人田地之象"],[5,"梦头面","梦面上麻子","主不光之兆。"],[5,"梦头面","梦头长面大与身等","主平添寿命"],[5,"梦头面","梦面戴假面具","\uFF08一\uFF09主得人覆庇之兆。\uFF08二\uFF09为诈昧羞惭之象。"],[5,"梦头面","梦面红","红而有喜色者,主有喜庆。红而如醉如怒者,主有愤怒丧亡之事。"],[5,"梦头面","梦面紫无光","主大凶。"],[5,"梦头面","梦取土培面","主显贵异常。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦耳在口中","将手移口于耳下,乃揖字也。主有客至,吉利之兆。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦耳被人割","梦耳受刑,主为祥之兆。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦被人打嘴","他人以手出力加我,主上上大吉。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦人跃人口中","主有狱中人扰乱之象。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦口大如斗","为正大光明宽宏通顺之象,亦甚吉利。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦口被人掩住","主为人禁闭,忍气吞声之兆。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦换齿","主子孙承继他人财产之象。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦齿落再生","梦此者,主父母安康,兄弟登贤,晚年荣显之兆。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦齿牙外露","此为争讼官司之兆,于迁移交易经营等事,均须耐守,庶可无咎。如起争讼,主邻里咸坐视不救。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦齿堕血出","\uFF08一\uFF09主破财之兆,又亲丁有灾。\uFF08二\uFF09主母病无救。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦齿落无血","此为大凶梦兆,主亡父母,丧妻妾,天子孙等优烦事,祸至灾生,无财可救。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦齿牙摇动","此为不宁之兆,父母有忧,子孙将危产业将散。迁移行动,有凶无吉。"],[5,"梦耳目鼻口\uFF08齿舌附\uFF09","梦跌落门牙","梦跌落上之门齿者,左主丧父,右主丧母。梦跌落下之门齿者,左主死兄,右主死弟,姊妹亦然。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦剃眉","梦此主安闲富贵之兆。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦两眉尽落","此梦主前程远大,年寿永长,乃光明之象也。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦发尽白","主多愁多寿,得白、得光之象。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦落发","主血虚财损之兆。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦发黑","此主福寿之征。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦发白复黑","\uFF08一\uFF09主沉冤难雪。\uFF08二\uFF09主寿永无疆。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦与皮骨","主脱俗超凡之兆,惟患病不宜。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦汗毛极长","主吉利,短则不祥。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦毫毛繁多","毫毛多主贵显,福多祸少。无毫毛者,气必不足。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦拔毛不落","\uFF08一\uFF09危难多事者梦之,主一钱不费。\uFF08二\uFF09宴居闲处者梦之,主百事不利。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦髯毛忽落","梦此者大不吉利,主子孙夭亡,妻妾殒折,父母有殃,兄弟殂落,家业凋零,血衰病重。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦添须","此为福寿之征,主家业增进寿算延长,商贾交易,主大得其利。"],[5,"梦眉发皮毛\uFF08胡髯附\uFF09","梦须长过身","为有余之兆。梦之者,主财帛丰盈,年寿孔永。"],[5,"梦手足全身","梦无左右手","主作事艰难,交易凶危。"],[5,"梦手足全身","梦露手骨","主掌握空虚。"],[5,"梦手足全身","梦手指出血","此主财旺气平之兆。"],[5,"梦手足全身","梦手足俱长","主兄弟富贵,子孙贤良,奴仆齐心,家道丰盛,左右逢源,无不如意"],[5,"梦手足全身","梦足污泥","主被污辱之兆。"],[5,"梦手足全身","梦添一脚","三足为鼎,有鼎立之数。梦之者,凡百可经撑持。"],[5,"梦手足全身","梦脚踏土中","主有立身之地,虽危亦必无患。"],[5,"梦手足全身","梦全见已身","此主有自知之明,君子梦之荣显,小人梦之康健。"],[5,"梦手足全身","梦裸体","此为出身显达之象,梦暑吉,梦寒凶,梦立吉,梦卧凶,梦仰吉,梦俯凶。"],[5,"梦手足全身","梦身瘦","主骨力强壮之象。少年梦之,虽贫无害。老年梦之,主吃老苦。富贵人梦之,俱属不祥。孕妇梦之,主大凶险。"],[5,"梦手足全身","梦体肥","\uFF08一\uFF09贫人主财来致富,富者主家业旺盛。中年梦之,亦主大吉。\uFF08二\uFF09病人梦之,无药可治。"],[5,"梦肩胁腹背","梦两肩打痛","主得人大力之兆。学者梦之,主精神百倍。勇士梦之,主气力争长。贫穷梦之,主有人扶助。衰病梦之主气旺神清。吉占也。"],[5,"梦肩胁腹背","梦立人肩上","此梦有独立不俱、为人尊重之象。"],[5,"梦肩胁腹背","梦肩挑担","此为任重之兆,梦此诸事大吉。"],[5,"梦肩胁腹背","梦蛇出腹中","\uFF08一\uFF09常人梦之,主有破财。\uFF08二\uFF09妇人梦之,主于其年得子。"],[5,"梦心胸乳脐","梦剖心","\uFF08一\uFF09此心窍通也。主诸难尽解,百忧可去。\uFF08二\uFF09主得仙道。"],[5,"梦心胸乳脐","梦取心入水中洗","有洗心涤虑、修德检身之象。"],[5,"梦心胸乳脐","梦心明如月","主心虚道明之兆,佳象也。"],[5,"梦心胸乳脐","梦乳自流","\uFF08一\uFF09此梦主充足有余之兆,衣食盈余,寿年孔永。产妇梦不祥。"],[5,"梦心胸乳脐","梦无脐","主有饥饿之象。"],[5,"梦心胸乳脐","梦脐中出烟","少年梦之,主有新婚之喜。"],[5,"梦血汗尿粪","梦舌尖出血","此梦主增进文思。口舌消散,病主心经,商贾多利。"],[5,"梦血汗尿粪","梦破伤无血","无精主父有殃,无血主母有患。"],[5,"梦血汗尿粪","梦放血与人","防有财物失脱之患。"],[5,"梦血汗尿粪","梦血淋身","梦此主功成名就,交易获利,子孙逢吉。"],[5,"梦血汗尿粪","梦浑身红血","无论富贵贫贱,梦此均主得财禄。"],[5,"梦血汗尿粪","梦血污衣服","\uFF08一\uFF09主意气扬扬,有自得之兆。\uFF08二\uFF09武人梦之,临阵大忌。"],[5,"梦血汗尿粪","梦汗污衣服","病人梦此，主有热病消除之象。"],[5,"梦血汗尿粪","梦浑身流汗","主消灾去疾。"],[5,"梦血汗尿粪","梦人与粪","梦此主诸凡方面,使用满前。"],[5,"梦血汗尿粪","梦与人粪","主不吉祥。"],[5,"梦血汗尿粪","梦扛粪回家","主大得财利,能成恒产。"],[5,"梦血汗尿粪","梦粪土堆积","此主积玉堆金之象。"],[5,"梦血汗尿粪","梦粪中坐","\uFF08一\uFF09主多所受累,到底难行。\uFF08二\uFF09梦在粪中坐起,则主后有好事至。"],[5,"梦血汗尿粪","梦索去粪土","主经商家业不利之兆。"],[5,"梦血汗尿粪","梦扫除尿粪","此主丧家之兆,急宜修省解禳。"],[5,"梦血汗尿粪","梦尿屎污身","\uFF08一\uFF09此梦贵人主增禄,富者主加息,行商主获利。\uFF08二\uFF09讼事不吉,如系病人,更当别占。"],[6,"梦仙佛","梦见仙经","主消除俗念,排遣世情,心安意适,气爽神清。有梦此得长寿者,有梦此成仙道者。"],[6,"梦仙佛","梦见太上老君","\uFF08一\uFF09主尘凡迥隔,仙骨将成。\uFF08二\uFF09文人主业进,常人得机遇,吉昌。"],[6,"梦仙佛","梦遇仙","\uFF08一\uFF09主有喜庆之事,功名贵显,财利丰亨。\uFF08二\uFF09修道之人梦之,主功丹成熟。"],[6,"梦仙佛","梦挂女仙像","主孕贤子。"],[6,"梦仙佛","梦赴仙宴","女子梦之,主有大吉庆。病人梦之,主有祸殃。"],[6,"梦仙佛","梦见佛法","梦此者,主得佛力普渡。"],[6,"梦仙佛","梦挂寿星像","主凡事大吉。"],[6,"梦仙佛","梦看佛","主亲有寿,妻有子,事事能逢凶化吉。"],[6,"梦仙佛","梦堂上有佛","女人梦之吉,常人梦之亦利,文人梦之大贵,惟在客梦之不祥。"],[6,"梦仙佛","梦见诸佛菩萨","主凡事吉利。"],[6,"梦仙佛","梦见仙佛群集","主喜气临门。子嗣大贵。"],[6,"梦仙佛","梦赴佛会","贵人主有刑狱,平民主有灾殃"],[6,"梦仙佛","梦问佛不答","主疾至灾临,急宜解镇。"],[6,"梦仙佛","梦拜佛欲动","此梦文人主大贵,常人主得财。"],[6,"梦仙佛","梦新塑佛像","\uFF08一\uFF09女人梦之,主有喜庆。\uFF08二\uFF09男子梦之,主大吉昌。\uFF08三\uFF09僧人梦之,主禅林丛胜之兆,亦主降慧之占。"],[6,"梦仙佛","梦见罗汉","主本身有死亡之厄。"],[6,"梦仙佛","梦诸佛下降","主有喜庆,遇善人,获善事。"],[6,"梦仙佛","梦诸佛与僧人密语","慎防闺门有私,主人无权,急宜解禳。"],[6,"梦仙佛","梦见如来佛","大喜。"],[6,"梦仙佛","梦见弥勒佛","\uFF08一\uFF09梦此主有喜事至。\uFF08二\uFF09受小人欺侮者,梦之主手握巨资,一生欢乐。"],[6,"梦仙佛","梦见释迦佛","主明心见性,可以参悟。僧人梦之,主智慧日进。"],[6,"梦仙佛","梦见观音大士","主得菩萨庇佑。女子梦之,主得佳儿,或有南海香愿未酬,应即速还。"],[6,"梦僧道","梦见僧","\uFF08一\uFF09男梦主女人吉,女梦主男子凶。\uFF08二\uFF09主父母有灾,子孙添喜。"],[6,"梦僧道","梦见法师","\uFF08一\uFF09高人梦之,主术业精进。\uFF08二\uFF09平人梦之,主疾病相侵。百凡务须改动,则鬼魅自然不生。"],[6,"梦僧道","梦与僧争论","主有闲气之事。"],[6,"梦僧道","梦玄师","主事有主盟,疾病痊愈。"],[6,"梦僧道","梦僧赐子","主得贵子之兆。"],[6,"梦神鬼","梦见门神","士子梦之,主功名显达大吉。"],[6,"梦神鬼","梦入神庙","主得财利,吉。"],[6,"梦神鬼","梦拜神","与上相同。"],[6,"梦神鬼","梦神召语","梦神告以吉凶之事,主有福禄喜事。"],[6,"梦神鬼","梦关圣呼己","贵人梦之,主救己之兆。"],[6,"梦神鬼","梦遇神指点","穷人梦之,主得名利。"],[6,"梦神鬼","梦祀诸神","主交易得财。"],[6,"梦神鬼","梦见正神","主诸事吉利。"],[6,"梦神鬼","梦见福神","主寿命延长。"],[6,"梦神鬼","梦见财神","主经商茂盛。"],[6,"梦神鬼","梦泰山神","凡人梦之,须戒僭逾之举,抑妄冀之谋,否则神必击之。"],[6,"梦神鬼","梦见阎王","此主阳数将尽,故见诸梦寐,不论男女老幼,梦之俱大不祥。"],[6,"梦神鬼","梦城隍神","\uFF08一\uFF09善人梦之,主有佳应。\uFF08二\uFF09常人梦之,主隐告谴罚。亟宜虔祀恳祷,更自改悔,方可无咎。"],[6,"梦神鬼","梦五路财神","此为执掌财帛之神,梦之主时连通达,转困为亨,乃大吉之兆也,能虔祀之,无不如志。"],[6,"梦神鬼","梦灶神","梦之主有火灾,或患眼痛,必禳解庶可无害。"],[6,"梦神鬼","梦见土地","\uFF08一\uFF09主人口不宁,家宅不安,须急禳之,可免。\uFF08二\uFF09主有迁移或动土之事。"],[6,"梦神鬼","梦月里嫦娥","\uFF08一\uFF09学道者梦之,主得长生之术。\uFF08二\uFF09常人梦之主得美妇。"],[6,"梦神鬼","梦织女星","\uFF08一\uFF09主夫妻远隔,离多会少之象。\uFF08二\uFF09主生慧女。\uFF08三\uFF09主得异锦裳服。"],[6,"梦神鬼","梦金龙四大王","\uFF08一\uFF09士子梦之,兆主发迹。\uFF08二\uFF09行人梦之,须防风波之险。"],[6,"梦神鬼","梦江河水神","出行及商人梦之,须防舟行有厄。必祈求祭祀，始吉。余者梦之,恐有水灾,或主有暴雨至。"],[6,"梦神鬼","梦雷神","梦之者,宜急自修省,毋罹天谴，仕宦尢须留意。"],[6,"梦神鬼","梦电母","梦之主得贤内助。"],[6,"梦神鬼","梦雨师","有滋生润泽之象,吉兆也。"],[6,"梦神鬼","梦风伯","\uFF08一\uFF09主舟行有惊,凡事须斟酌行之。\uFF08二\uFF09士子梦之,主为佳兆。"],[6,"梦神鬼","梦子孙娘娘","主子孙昌大,福泽久长。"],[6,"梦神鬼","梦天医","\uFF08一\uFF09常人梦之,主一生无疾病,生子为世名医。\uFF08二\uFF09医家梦之,主大行其道,多获福利。\uFF08三\uFF09病人梦之,主不日痊可,定占勿药之喜。"],[6,"梦神鬼","梦招财童子","学子主才思英发,行商主得利远方,或进得力人口。"],[6,"梦神鬼","梦钟馗","\uFF08一\uFF09武士梦之大吉。\uFF08二\uFF09病人梦之,早治后事;常人梦之慎防失跌之灾。"],[7,"梦诸禽","梦见玄黄鹤","\uFF08一\uFF09有父母者梦之,主父母长寿,无则己身当之,大吉之兆也。\uFF08二\uFF09修炼家梦之,主有真仙来渡,白日飞升。"],[7,"梦诸禽","梦见白鹤","\uFF08一\uFF09常人梦之,寿逾百岁。\uFF08二\uFF09孕妇梦之,主得贵子,可望显荣。\uFF08三\uFF09修炼家梦之,主有天仙降临,可望羽化。"],[7,"梦诸禽","梦鹤投入怀","主生慧女。\uFF08梦见雌鹤\uFF09主得美女,但不寿。"],[7,"梦诸禽","梦孔雀飞舞","\uFF08一\uFF09贵家梦之,主功名显达,婚姻皆贵。\uFF08二\uFF09孕妇梦之,主生才子。\uFF08三\uFF09下人梦之,仍为皂隶。"],[7,"梦诸禽","梦得鸿雁","主无往不利之兆,居家梦之,五味皆宜。"],[7,"梦诸禽","梦燕飞","\uFF08一\uFF09主有燕会喜乐之兆。\uFF08二\uFF09孕妇梦之,主生贤子。\uFF08三\uFF09行人梦之,主得归家。\uFF08四\uFF09困者梦之,主得财利。\uFF08五\uFF09病人梦之,主病可愈。"],[7,"梦诸禽","梦白鹇","\uFF08一\uFF09少年梦之,主非佳兆,有白日闲过忧。\uFF08二\uFF09老年梦之,主有白髡安闲之福。"],[7,"梦诸禽","梦见赤鸟","梦此孕育主生贵子,久雨主天放晴,久病主灾消福至,久约主否极泰来。若梦无足赤鸟入室,须防火灾。"],[7,"梦诸禽","梦见白颈鸦","\uFF08一\uFF09贫人主得财。\uFF08二\uFF09受屈者主得白。\uFF08三\uFF09孕妇梦之,主生孝子。\uFF08四\uFF09病人主之凶兆。\uFF08五\uFF09有丧服者,主为佳兆。"],[7,"梦诸禽","梦身化乌","主诸事成就。"],[7,"梦诸禽","梦鸳鸯戏水","戏水为喜乐之兆,梦之者,主婚姻和合,室家欢庆。"],[7,"梦诸禽","梦瓦化为鸳鸯","主女人暴死之兆。"],[7,"梦诸禽","梦鸳鸯栖止","主福寿骈臻之瑞徵。"],[7,"梦诸禽","梦见鹦鹉","主忧虑亡人之象。"],[7,"梦诸禽","梦鹦鹉传言","主有巧言如簧之虑。梦之者,须正德修身,防末然。"],[7,"梦诸禽","梦雄鸡生子","须防有口舌是非。"],[7,"梦诸禽","梦雌鸡啼","主有灾殃。"],[7,"梦诸禽","梦见白鸡","以鸡所止之年日月,为有死亡之虑。"],[7,"梦诸禽","梦鸡","梦此者,淹蹇之中,主有吉祥,但不可忘戒慎。"],[7,"梦诸禽","梦与鸡犬","主路遇小人之象。"],[7,"梦诸禽","梦鸡鸣水中","\uFF08一\uFF09主醉后有来口舌之祸。\uFF08二\uFF09作事顺遂者梦之反能得利。"],[7,"梦诸禽","梦鸡鸭同群","主畜养众多之兆。富贵主日新之象,贫贱为多利之徵,又有和悦之状。"],[7,"梦诸禽","梦鸭抱蛋","此为扶阴抑阳之象,有病人梦之,病即可愈,兼为寿徵。"],[7,"梦诸禽","梦鹅鸭水上同游","是为所居得所之佳兆,主妻妾情意和洽。"],[7,"梦诸禽","梦鸲鹆\uFF08即八哥\uFF09","梦此者忧喜不一,或先忧后乐,或乐极生悲。春夏梦之多吉,秋冬梦之多凶。"],[7,"梦诸禽","梦己化为鸲鹆","主为文人才子。"],[7,"梦诸禽","梦鹌鹑","主动循礼法之象。"],[7,"梦诸禽","梦见练雀","\uFF08一\uFF09争讼者梦之,主尚淹濡不释。\uFF08二\uFF09常人梦之主丧伯叔兄弟。"],[7,"梦诸禽","梦玉雀入怀","妇人梦之,主得贵子。"],[7,"梦诸禽","梦赤雀","主家门兴盛之兆。"],[7,"梦诸禽","梦黄雀","\uFF08一\uFF09中年人梦之,主得超迁。\uFF08二\uFF09老年已致仕者梦之,恐为辞世之兆。"],[7,"梦诸禽","梦麻雀","此为小人成群之象。常人梦之小心谨慎,不至为小人所忌。富者梦之,防有窃盗之灾,但亦小小损失耳。"],[7,"梦诸禽","梦子规月下啼","\uFF08一\uFF09富贵梦之,主宴乐歌舞,通宵未归之兆。\uFF08二\uFF09行人梦之,主动故乡之思。"],[7,"梦诸禽","梦画鸟","被幽禁者,梦此自能脱罪。"],[7,"梦诸禽","梦大鸟来庭","主以文章鸣世。"],[7,"梦诸禽","梦与恶鸟","孕妇梦之,主不祥之兆。"],[7,"梦诸禽","梦鸟入口","与梦大鸟同兆。"],[7,"梦诸禽","梦鸟飞蝠逐","主死亡之兆。"],[7,"梦诸禽","梦擒好鸟","主大吉利。"],[7,"梦诸禽","梦与羽毛","主衣冠更换之徵。"],[7,"梦诸兽","梦虎变人","\uFF08一\uFF09孕妇梦之,主生文武全才,为当世豪杰。\uFF08二\uFF09仕宦梦之,主权位共常崇隆。"],[7,"梦诸兽","梦白虎","\uFF08一\uFF09仕宦梦之,主长刑狱。\uFF08二\uFF09常人梦之,为凶丧之兆。"],[7,"梦诸兽","梦虎伤人","主战争失利。"],[7,"梦诸兽","梦骑狮","\uFF08一\uFF09主有威武,亨禄位,为当代大将。\uFF08二\uFF09僧人梦之,为文殊菩萨化身,主成正果。"],[7,"梦诸兽","梦与猛兽","孕妇梦之,主不祥之兆。"],[7,"梦诸兽","梦豹入家中","\uFF08一\uFF09常人梦之,恐有官司,兼防冠盗。\uFF08二\uFF09孕妇梦之,主生文武全才之男。"],[7,"梦诸兽","梦大象","主得显宦,然不能善终。"],[7,"梦诸兽","梦象入户","\uFF08一\uFF09男子梦之,主在官宦。\uFF08二\uFF09女子梦之,主得贤子。\uFF08三\uFF09病人梦之,主能除去病根,心神复正。"],[7,"梦诸兽","梦骑象","主身荣利遂之象。"],[7,"梦诸兽","梦犀牛涉水","\uFF08一\uFF09军士梦之,水战大胜。\uFF08二\uFF09商人梦之,主江泛海,必获奇珍。\uFF08三\uFF09旅行梦之,遇险得济。\uFF08四\uFF09疾病梦之服药必痊。"],[7,"梦诸兽","梦骆驼负囊行","\uFF08一\uFF09梦于日中行者,主有好事至,但非安闲之兆。\uFF08二\uFF09梦于月下行者,主为乱世。\uFF08三\uFF09梦于暗中行者,主为杀身成仁之徵,然非吉兆也。"],[7,"梦诸兽","梦豹狼围困","此为群凶扰乱之兆。居官恐来党祝。在家慎防寇盗。出行商贾,主中途不免劫掠,戒备为贵。"],[7,"梦诸兽","梦鹿","梦得鹿,主富贵。梦失鹿,主贫困。梦鹿生,则身存。梦鹿死,则身死。百不爽一。"],[7,"梦诸兽","梦马","主有远行奔走之事。"],[7,"梦诸兽","梦马舞","主有火起。"],[7,"梦诸兽","梦马无头","主不得善终。"],[7,"梦诸兽","梦万马","梦此者,主心事不宁,家内扰乱,须静以镇之,安以待之,勿轻举妄动,乃吉。"],[7,"梦诸兽","梦马在云中","主为出行意期,归期末定之兆。"],[7,"梦诸兽","梦四马六马同驾","此为驾车安行之象,虽在贫贱患难之中，亦仍无害,乃大贵之兆也。"],[7,"梦诸兽","梦乘马入深山","梦此主非佳兆,有行路难及无归期之象。"],[7,"梦诸兽","梦己乘马入云","此主乘云得路之兆,艰难险阻之际,梦之大吉。"],[7,"梦诸兽","梦神乘马升天又堕下","此为见险而动、动而能免大险之象。"],[7,"梦诸兽","梦神乘马入云","是安其心于危难之际也。"],[7,"梦诸兽","梦神乘马直上天空","主大贵之兆。"],[7,"梦诸兽","梦牵羊","此为一阳来复,富贵梦之,主生贵子;流离颠沛梦之，主家道兴盛。又病疾痊愈,讼事和息,怨怒消解。"],[7,"梦诸兽","梦见赤羊","主大贵天下。"],[7,"梦诸兽","梦空羊人狱","主出仕为百里侯。"],[7,"梦诸兽","梦驴","主与人有官司。"],[7,"梦诸兽","梦见骡","主能得货利,但多劳无逸。"],[7,"梦诸兽","梦犬死","\uFF08一\uFF09此为水旺火息之兆,须以本身之德行占之:有德为吉,无德为凶。\uFF08二\uFF09主得食物之兆。"],[7,"梦诸兽","梦己变犬","\uFF08一\uFF09主己为盗贼。\uFF08二\uFF09主亡人有冥司受罪。"],[7,"梦诸兽","梦犬自天下","行为不正之人,梦之大凶。守正者梦之,则又主勇夫来助之兆。"],[7,"梦诸兽","梦刍狗","\uFF08一\uFF09主得酒食。\uFF08二\uFF09主有堕车折足之象。\uFF08三\uFF09主有失火之兆。"],[7,"梦诸兽","梦两犬对言","犬对言为狱字,主遭刑狱。"],[7,"梦诸兽","梦狗肉一片","\uFF08一\uFF09主得大贵。\uFF08二\uFF09防有官司口舌"],[7,"梦诸兽","梦大母猪","\uFF08一\uFF09仕官梦之,主管仓库。\uFF08二\uFF09常人梦之,主富有田产。"],[7,"梦诸兽","梦猪被杀复活","\uFF08一\uFF09此主刑狱之事,或无故被囚,或死罪遇赦,或宿冤不解。\uFF08二\uFF09子死主再育一子。"],[7,"梦诸兽","梦己变猪","此为不得其死之兆。"],[7,"梦诸兽","梦猫吞活鱼","此为成家立业之征,主贸易山左,能获大利,且前程远大。"],[7,"梦诸兽","梦群猫相斗","此主暮夜有戎之兆,但于己无患。若梦己所畜之猫,被他家猫咬伤,则主下人有灾。"],[7,"梦诸兽","梦猫捕鼠","\uFF08一\uFF09梦此主得财。\uFF08二\uFF09须防子媳有灾。\uFF08三\uFF09出行人梦之,有不得归之叹。"],[7,"梦诸兽","梦猫食蝴蝶","此梦不祥,恐有阴私小人,陷害正人,须谨防之。"],[7,"梦诸兽","梦鼠变人","\uFF08一\uFF09此为生男之兆,老年梦之,主生幼子。\uFF08二\uFF09僧道梦之,验在他人。\uFF08三\uFF09老妇梦之,须防口舌之事,或主子姓褚姓人为之劝解,亦得改祸为福。"],[7,"梦诸兽","梦鼠伏盖下","主逃窜之象。虽中人构之,遁向西南去吉。"],[7,"梦诸兽","梦猿猴献果","\uFF08一\uFF09主有喜庆宴会之事。\uFF08二\uFF09主福寿兼全,名利双收。"],[7,"梦诸兽","梦狐半济仍折回","主有难阻行之兆,出行不谕水陆,均须善自预防。女子梦此,持身须严,远避小人为是。"],[7,"梦水族","梦群蛇缘城出","主其地有焚毁屠戮之惨,应急避为是。"],[7,"梦水族","梦鲸鱼","\uFF08一\uFF09行人梦之,主有远信。\uFF08二\uFF09求功名者梦之,主必得好音。\uFF08三\uFF09恶人梦之,不得善终。"],[7,"梦水族","梦鳄鱼","商人梦之,陆路无险阻,河海有灾晦,当慎防之。"],[7,"梦水族","梦人馈鱼","\uFF08一\uFF09梦馈活鱼,主得财帛。\uFF08二\uFF09梦馈腥鱼,主得饮食。\uFF08三\uFF09梦馈乾鱼,主得羡馀。皆喜庆之兆也。"],[7,"梦水族","梦鲤鱼","此为能变化之兆。孕妇梦之,主生共常之人,但应在四九。"],[7,"梦水族","梦钓鱼","主得酒食。"],[7,"梦水族","梦钓得大鱼","\uFF08一\uFF09为联婚大家之征。\uFF08二\uFF09求财主能称心,谋望自然如意。"],[7,"梦水族","梦举网得鱼","\uFF08一\uFF09仕官梦之,主得治理之效。\uFF08二\uFF09常人梦之,主能得酒食。"],[7,"梦水族","梦鱼食稻米","\uFF08一\uFF09主大水为灾,年岁荒歉,民人饥困。\uFF08二\uFF09丰年梦之,恐有寇盗发生,妨害农事。"],[7,"梦水族","梦蟹游满田","主兵戈扰攘,寇盗纵横,须预防之。"],[7,"梦水族","梦黄甲蟹","\uFF08一\uFF09疾病词讼梦之,必主解散。\uFF08二\uFF09交易婚姻。"],[7,"梦水族","梦蛤蜊","蛤为合,蜊为利。凡梦此者,宜合不宜分。如商贾梦之主合本始多利;兄弟梦之,主分产不成;出行梦之,主合伴为佳；婚姻梦之,主得就为美。"],[7,"梦水族","梦蚌","梦之有凡事和合之象,主婚姻佳良,子嗣贤美。"],[7,"梦水族","梦石决明","主眼目光明。"],[7,"梦水族","梦鳝鱼\uFF08鳝、善同音\uFF09","\uFF08一\uFF09主迁善改过,戒杀放生。\uFF08二\uFF09小人梦之主纵口腹之欲。"],[7,"梦水族","梦蟾蜍","道流梦之,主必成仙。"],[7,"梦水族","梦蛙闹","\uFF08一\uFF09为鼓乐喧天之兆,主有喜庆之事。\uFF08二\uFF09牧民者梦之,主疑狱得决,冤罪分明。"],[7,"梦昆虫","梦青蚨飞来","梦此主得横财,但恐不能经久。"],[7,"梦昆虫","梦扑杀蝴蝶","\uFF08一\uFF09梦此亦主得外财。\uFF08二\uFF09主生意兴隆之兆。\uFF08三\uFF09有祸必解,有忧必散事必成,有求必得。"],[7,"梦昆虫","梦蝴蝶飞入帐中","主出行之象。"],[7,"梦昆虫","梦蜻蜒飞满空中","主取悦于人之象,能虚己应人,则吉。"],[7,"梦昆虫","梦蜻蜒自食其尾","\uFF08一\uFF09不自食己资之象。\uFF08二\uFF09主得有珍宝之兆。"],[7,"梦昆虫","梦蟋蟀","梦此为及时行乐之兆。"],[7,"梦昆虫","梦蟋蟀鸣","主有忧勤之思。"],[7,"梦昆虫","梦飞蛾","主婚姻有能成之兆。"],[7,"梦昆虫","梦蝗虫","\uFF08一\uFF09主子孙繁盛,福寿增加。\uFF08二\uFF09主生男荣华,家庭衍庆。"],[7,"梦昆虫","梦蝗飞水面","主得大富贵。贫人梦之,主绝处逢生,凶中得吉。"],[7,"梦昆虫","梦蝗虫飞去","荒年梦此,主有难可解,遇险得救。"],[7,"梦昆虫","梦灯蛾扑灭火","主娶女有虚惊。"],[7,"梦昆虫","梦养蚕","仕宦梦之,主得显贵。"],[7,"梦昆虫","梦蝉鸣","主高人逸士声应气求之兆。若梦蝉鸣声,有远信至。"],[7,"梦昆虫","梦螳螂窥户","\uFF08一\uFF09主有小人前来窥探。\uFF08二\uFF09主机密之事难于预防。"],[7,"梦昆虫","梦满树胡蜂房","此为小人蜂聚之象。病人梦之,务须祈祝。"],[7,"梦昆虫","梦蜜蜂来刺","主有作事被谤、小人陷害之兆,慎之为妙。"],[7,"梦昆虫","梦蜜蜂采花","此为有大人主张之梦兆,主遇事无私,守正不二，吉征也。"],[7,"梦昆虫","梦蚕蛾出茧中","\uFF08一\uFF09主有婚姻喜事至。\uFF08二\uFF09求子者梦之,主生贵子。\uFF08三\uFF09养蚕家梦之,不见休咎。"],[7,"梦昆虫","梦胡蜂","\uFF08一\uFF09梦此为起家之吉兆。\uFF08二\uFF09主有螟蛉入嗣之征,唯求子不祥。"],[7,"梦昆虫","梦蝙蝠食蚊虫","主有福人来解救之象,可喜可贺。"],[7,"梦昆虫","梦蝙蝠自天飞下","此为天神赐福之兆,主有大喜庆事。"],[7,"梦昆虫","梦扑杀蚊见血","\uFF08一\uFF09主有受伤之象。\uFF08二\uFF09武人梦之,主杀人之兆。"],[7,"梦昆虫","梦蚊蝇如市","梦蚊主残刻,梦蝇主奸谗,俱属为祥,须慎防之。"],[7,"梦昆虫","梦蝇虎集背上","君子梦之大吉,小人梦之大凶。"],[7,"梦昆虫","梦蜘蛛","\uFF08一\uFF09主本日即有喜事。\uFF08二\uFF09孕妇梦之,主有忧疑。"],[7,"梦昆虫","梦喜蛛","梦此亦主有喜事之兆,但虽喜极微。"],[7,"梦昆虫","梦蜈蚣成群","梦此主所交与多非善类,务绝交以免害。"],[7,"梦昆虫","梦蚯蚓入室","主有逃避之人,来求陷居。"],[7,"梦昆虫","梦蜒蚰在几上","梦此有难信人言之象。"],[7,"梦昆虫","梦蜗牛满野","梦者利女人,然主贫穷。"],[7,"梦昆虫","梦狗蝇飞来","\uFF08一\uFF09梦此者,主得小人之财,可以不劳而获。\uFF08二\uFF09病人梦之,所患必痊。\uFF08三\uFF09困穷梦之,无悔。"],[7,"梦昆虫","梦萤入腹中","\uFF08一\uFF09此梦为明心之兆，有赦过宥罪之祥。遇险得脱,遇能即解。\uFF08二\uFF09用火务须小心。"],[7,"梦昆虫","梦萤无头无翅","此鬼祟索食之梦也。梦此者,宜设醮做斋。有病患难愈者,须放水陆灯,如中元所做法事。"],[7,"梦昆虫","梦群蚁扛萤","\uFF08一\uFF09士人梦之,主被人诬蔑。\uFF08二\uFF09病人梦之,主有虫在经络。"],[7,"梦昆虫","梦蚁排陈","主有人来归附之兆。"],[7,"梦昆虫","梦见蚁王","仁慈之人梦之,主有脱险消难之庆。"],[7,"梦昆虫","梦虫自耳中飞出","此有灾消祸散之梦,惟病人梦之不祥。"],[7,"梦昆虫","梦臭虫","主得有财物之象,但非一人所有,故美中似有不足。"],[7,"梦昆虫","梦捉虱","主事事求己之象,无论求财延寿,去病解愁,均由自己作主。"],[7,"梦昆虫","梦蚤虱满床","主居之不安之兆,能舍已从人,则灾厄自解。"],[7,"梦昆虫","梦与虫鼠","主家计耗散之征。"],[7,"梦树木","梦入深林","主获财帛。"],[7,"梦树木","梦林中坐","主卧病未能起。"],[7,"梦树木","梦树木成林","梦此为扬眉吐气之象,若能再加培植,定主家吉人安,利遂名成。"],[7,"梦树木","梦之树林","梦此者,主能栽培阴德,以致昌隆。士人主光显门庭。常人主身家兴旺。大吉大利之兆也。"],[7,"梦树木","梦见绿林","主茂盛吉利。"],[7,"梦树木","梦登大树","\uFF08一\uFF09梦此者,主防倾厄,又少光彩。\uFF08二\uFF09梦登大树,则主大吉之兆,求名得名,求利得利。"],[7,"梦树木","梦木现五色","此为祥瑞之征。文人梦之,名高天下。商贾梦之,利收四海。孕妇梦之,必定生男。"],[7,"梦树木","梦种树庭中","此主父母老年强固,身体发荣之兆。"],[7,"梦树木","梦枯木再花","\uFF08一\uFF09此为家业重振之象,主子孙气象维新,晚来荣茂。\uFF08二\uFF09主妇当再嫁,孕必重女,居无旺气,讼当复发。"],[7,"梦树木","梦大树复折","梦此主家主死亡,得力之人,忽生阻折。"],[7,"梦树木","梦身在树上","梦此主名利旁落,宅舍不宁,病难痊可。"],[7,"梦树木","梦身在树忽折","主有死伤。"],[7,"梦树木","梦家庭树生果","梦此主大有收成,无子得子,失业得业,事有头绪,谋望成就,老人安享,官讼理直,功名到手,婚姻和谐。"],[7,"梦树木","梦身入木中","人死方入木中。梦此者,主身危之象。"],[7,"梦树木","梦践木","主材在众人之上。"],[7,"梦树木","梦木生堂上","主有不利父母之危。"],[7,"梦树木","梦松","\uFF08一\uFF09贵人梦之,主禄位高迁。\uFF08二\uFF09士人梦之,主青云路达。\uFF08三\uFF09妇人梦之,主生贵子。\uFF08四\uFF09商贾梦之,主财利必得。"],[7,"梦树木","梦松生户前","主即死亡。"],[7,"梦树木","梦松生腹上","主得大贵。"],[7,"梦树木","梦柏","梦此主精神强健,挺秀岁寒,惜不合时宜耳。"],[7,"梦树木","梦砍去松柏","主父母弃养。"],[7,"梦树木","梦椿叶调零","宜勤加爱护。"],[7,"梦树木","梦椿被雨淋","主亲有涕泣之忧。"],[7,"梦树木","梦椿发芽","主父寿算无穷。"],[7,"梦树木","梦樁树茂盛","主父业隆盛。"],[7,"梦树木","梦椿覆庭下","主己身得荫庇。"],[7,"梦树木","梦椿根重发新根","主生幼弟。"],[7,"梦树木","梦枣生屋上","枣字似重来,重来为呼魄之象,主即死。"],[7,"梦树木","梦梧桐","\uFF08一\uFF09梦此主品行高洁,占士林之光,所虑者早凋耳。\uFF08二\uFF09主得遇知交。"],[7,"梦树木","梦枫生腹上","主得清高之子。"],[7,"梦树木","梦居榆树","主衣食丰,无求自足之象。"],[7,"梦树木","梦杨柳","\uFF08一\uFF09主与友人相别,或有章台之恋。\uFF08二\uFF09士人梦之,有士女同心之结。\uFF08三\uFF09女子梦之,主夫婿轻狂薄幸之兆。"],[7,"梦树木","梦桑","\uFF08一\uFF09主有操持名显利实,虽居不定,虽失可得。\uFF08二\uFF09桑音同丧,病人梦之,殊为可虑。"],[7,"梦树木","梦荆棘","\uFF08一\uFF09梦此主作事有阻,患病须防,宅人无人,利难到手。\uFF08二\uFF09士人梦之则吉。"],[7,"梦树木","梦斫乔木","主父仙游。"],[7,"梦树木","梦斫去紫荆","主骨肉散离。"],[7,"梦谷类","梦五谷","主得财帛,家业丰富,吉兆也。"],[7,"梦谷类","梦与五谷","主田丰家足之兆。"],[7,"梦谷类","梦割禾失禾","禾失为“秩”,梦此主得官秩。"],[7,"梦谷类","梦磨麦连落","夫与子并散失者,梦之主得复见,有骨肉团圆之兆。"],[7,"梦谷类","梦禾稼","主财气旺盛。"],[7,"梦谷类","梦赐粟","主孝友之兆。"],[7,"梦蔬菜","梦葵菜满城","用兵者梦之,主必败之兆。"],[7,"梦蔬菜","梦金花菜","\uFF08一\uFF09仕宦梦之,主能显扬。\uFF08二\uFF09常人梦之,主名利通达。田产增多,成谋遂意。\uFF08三\uFF09求子不宜。"],[7,"梦蔬菜","梦紫花菜","梦此出行主毫无险阻,贸易主满获财货,文人主才藻丰富,仕官主贵不言可。"],[7,"梦蔬菜","梦山药","少壮者梦之,主添精益髓。\uFF08二\uFF09高年人梦之。主却病延年。\uFF08三\uFF09患虚损之症梦之,其病即愈。"],[7,"梦蔬菜","梦水芹菜","\uFF08一\uFF09梦采之者,主事神有敬信之诚。\uFF08二\uFF09梦食之者,主治家俭约。"],[7,"梦蔬菜","梦紫茄","\uFF08一\uFF09梦生食,主生男;梦熟食,主生女。\uFF08二\uFF09梦人授之,主得童仆,梦授与人,主善贸易。"],[7,"梦蔬菜","梦芋","出军梦之,主粮饷有余。行旅梦此,主囊资充足。贫困梦此,主饔飧有备。难人梦此,亦不至断火绝食。"],[7,"梦蔬菜","梦银茄","君子梦之,作事多疑。常人梦之,出行遇贵,受屈得白,患病得苏,忧苦遇乐。"],[7,"梦蔬菜","梦石花菜","\uFF08一\uFF09文人梦之主才思增进,锦上添花。\uFF08二\uFF09商贾梦之,主大获珍宝,无中生有。\uFF08三\uFF09女子梦之,此物主不能孕育。"],[7,"梦蔬菜","梦王瓜","\uFF08一\uFF09梦取王瓜者,主祭神受福,以隆孝享。\uFF08二\uFF09梦食王瓜者,主有病即治,目暗复明,脾泄便止。"],[7,"梦蔬菜","梦芥菜","常人梦之,主有癣疥之患。"],[7,"梦蔬菜","梦与葱菜","主财丰利遂之兆。"],[7,"梦蔬菜","梦香椿嫩菜","\uFF08一\uFF09主寿征。\uFF08二\uFF09诗人梦之,主有游春之兴。\uFF08三\uFF09女子梦之,主有怀春之思。"],[7,"梦蔬菜","梦丝瓜葫芦","梦此主凡事仍旧,勿妄更改。有病即愈,不需医药。患天行痘疹梦此,主小口无伤。"],[7,"梦蔬菜","梦磨菇","\uFF08一\uFF09常人梦之,主为比昵群小之兆。\uFF08二\uFF09长斋女人梦之,主有听讲说法之事。\uFF08三\uFF09病人梦之,远许佛愿。\uFF08四\uFF09访道者梦之,主必遇真仙。"],[7,"梦蔬菜","梦苋菜","未婚之人梦之,主得贤妇,且产佳儿。"],[7,"梦蔬菜","梦青云菜","\uFF08一\uFF09常人梦之,主有游观之乐。\uFF08二\uFF09远行梦之，主得归家之期。"],[7,"梦蔬菜","梦莼","久客梦之,主得还乡,且主有远信至。"],[7,"梦蔬菜","梦大蒜数头","主延长寿算之兆,吉祥之梦也,然惟仁者始能梦之。"],[7,"梦瓜果","梦杏","常人梦之,主生贵子。"],[7,"梦瓜果","梦食杏实","\uFF08一\uFF09主家门喜庆,获保康宁。\uFF08二\uFF09患难梦之,主有人力扶助。无往不利。\uFF08三\uFF09久病梦之,主血脉调和,渐得痊可。"],[7,"梦瓜果","梦梅","梦之必主超伦出群。"],[7,"梦瓜果","梦桃","梦之者,主有守御,善辟不祥。"],[7,"梦瓜果","梦人馈一桃一梨","主为人解释冤枉之兆。"],[7,"梦瓜果","梦梨","\uFF08一\uFF09主有盛宴之兆,或主有适意之事。\uFF08二\uFF09病人梦之不宜,以梨、离同音,神离去,不吉也。"],[7,"梦瓜果","梦剖梨","分离之人梦之,主有团聚之象。"],[7,"梦瓜果","梦李","\uFF08一\uFF09梦此恐有牢狱之忧。\uFF08二\uFF09仁人梦之,主兰桂挺秀。"],[7,"梦瓜果","梦枣","\uFF08一\uFF09枣、早同音,梦之者,主名利早得、婚姻早成、子嗣早招,乃喜气重重之象也。\uFF08二\uFF09病疾争讼,梦之皆不宜。"],[7,"梦瓜果","梦食粟","主作事费力。"],[7,"梦瓜果","梦粟在衣袖","主事已成就之象。"],[7,"梦瓜果","梦身负多粟","主艰辛不释之兆。"],[7,"梦瓜果","梦粟壳","主气运尚不能通。"],[7,"梦瓜果","梦蟠桃","梦此主士人即显达,孕妇生贵子,老年有寿征,出行遇贵人,择配得佳婿,疾病易痊可,争讼必得胜,诸事吉祥,无往不利。"],[7,"梦瓜果","梦石榴","\uFF08一\uFF09主功名早遂,子嗣多贤。\uFF08二\uFF09疾病梦之无害。\uFF08三\uFF09讼事须防受责。"],[7,"梦瓜果","梦枳","梦此主作事无望。"],[7,"梦瓜果","梦柚","主有成就之意,或得大财,或享大名,或得异味,大吉之征也。"],[7,"梦瓜果","梦橙","梦此主必遇小人,外貌美而中藏叵测,宜远避之为佳。"],[7,"梦瓜果","梦枇杷","梦之者主骨肉和平,同枝共茂。"],[7,"梦瓜果","梦杨梅","\uFF08一\uFF09常人梦之,主生恶疮,败散之光也。\uFF08二\uFF09君子梦之,主有杨眉吐气之日。"],[7,"梦瓜果","梦林擒","主吉事重至,或得美产,或娶娇妇,或添子嗣,或益财源,应验如神。"],[7,"梦瓜果","梦核桃","此梦主有远方或阔别经年者来谒,或欲借居,但志向各异,终难契合。"],[7,"梦瓜果","梦橄榄","主先难后易,苦尽甘来之兆。"],[7,"梦瓜果","梦葡萄","\uFF08一\uFF09梦此主得美酿。\uFF08二\uFF09病人梦之,主死征将至。"],[7,"梦瓜果","梦荔枝","荔、离同音,有先丧本之象。"],[7,"梦瓜果","梦荔枝","荔、离同音,有先丧本之象。家宅须速迁移;疾病不易脱离;生子主继他姓,或出家为僧道;求财无多,亦不脱空。"],[7,"梦瓜果","梦桂圆","圆之为言元也。主谋事可成,婚姻有望,亦主得贵人提拔,大吉。"],[7,"梦瓜果","梦食松子","\uFF08一\uFF09此为贵征,又为寿征。梦之者,主身荣家富,灾消病除。名高誉满,子贵孙贤,修行者主长生不老。\uFF08二\uFF09孕妇梦之,生子定然秀慧。"],[7,"梦瓜果","梦得瓜","主纯孝感格之兆。"],[7,"梦瓜果","梦木瓜枯","主产女有厄。"],[7,"梦杂品","梦紫菱","主有头角峥嵘之兆。"],[7,"梦杂品","梦芡实","梦之者,主作事有益无损。"],[7,"梦杂品","梦莲荷","梦此主婚事有成,六甲生男,财利无比,家居畅适,疾病离床。"],[7,"梦杂品","梦采荷","主不吉利。"],[7,"梦杂品","梦采荷无根","\uFF08一\uFF09主少年夭折,疾病可危。\uFF08二\uFF09争讼可解。"],[7,"梦杂品","梦食甘蔗","梦此为渐入佳境之象:文人主学问日进,仕官主禄位日隆,商贾主财利日丰,老年主筹算日高。"],[7,"梦杂品","梦食藕","主生男女多智慧秀巧。"],[7,"梦花卉","梦腊梅花","\uFF08一\uFF09主亲可长寿,病可望痊。\uFF08二\uFF09主无子嗣。"],[7,"梦花卉","梦折梅花","主子嗣有灾。"],[7,"梦花卉","梦种梅花","主生子清超。"],[7,"梦花卉","梦红杏","主功名发兆之征。"],[7,"梦花卉","梦栽杏花","主才名出众。"],[7,"梦花卉","梦簪兰花","主得佳人。"],[7,"梦花卉","梦嗅盆兰","为贫得财利之象。"],[7,"梦花卉","梦水仙花","\uFF08一\uFF09梦此当大贵,但赋质纤弱,恐不寿而天。\uFF08二\uFF09孕妇梦之,主生佳女。\uFF08三\uFF09行商梦之,主获半利。\uFF08四\uFF09常人梦之,主病散讼理,移居多吉,谋望有成,走失易获,器物不失。"],[7,"梦花卉","梦牡丹花","主大富贵之征。"],[7,"梦花卉","梦折牡丹花","女主人不利。"],[7,"梦花卉","梦栽石榴","主姻缘和合。"],[7,"梦花卉","梦折石榴花","主子孙殒灭。"],[7,"梦花卉","梦迎春花","主生意旺盛,子嗣英秀。若梦在深秋,亦只须静守待时。"],[7,"梦花卉","梦芍药花","梦此主居所须迁,虽富不久,有病难起,讼事易完,孕必生女。"],[7,"梦花卉","梦萓花","\uFF08一\uFF09主慈闱有庆。\uFF08二\uFF09孕妇梦之,主必生男。\uFF08三\uFF09名利无忧。"],[7,"梦花卉","梦萱风吹","主母有病痛。"],[7,"梦花卉","梦萱枝忽枯","主哀子怨慕。"],[7,"梦花卉","梦折去萱花","主父母归天,才名两失。"],[7,"梦花卉","梦菊","\uFF08一\uFF09梦之主晚年大就,利在秋冬两收。\uFF08二\uFF09为守正不阿之象。"],[7,"梦花卉","梦迎春花","此梦生男,主为人仆役;生女,主为人侧室。"],[7,"梦花卉","梦月季花","\uFF08一\uFF09此为小吉之兆,文人梦之,小试之,主得小利。\uFF08二\uFF09疾病去怯,讼狱非宜。"],[7,"梦花卉","梦玫瑰花","此为子孙兴隆之兆,身享荣华,老年主子孙贵显。"],[7,"梦花卉","梦头戴玫瑰花","主生贵子。"],[7,"梦花卉","梦折桃花","主寿命不永。"],[7,"梦花卉","梦芙蓉花","\uFF08一\uFF09梦此主为过眼即退之象,以虽荣而不能经久也。\uFF08二\uFF09女人梦之,主招贤夫。"],[7,"梦花卉","梦向日葵","主凡事遇贵人提拔,吉利之征也。"],[7,"梦花卉","梦茶花","梦此主家最吉,婚姻早定,花前子后。患病主火症。"],[7,"梦花卉","梦栀子花","主生佳儿。"],[7,"梦花卉","梦杜鹃花","主多忧思悲哀之兆。"],[7,"梦花卉","梦鸡冠花","主昌明之兆,百事俱吉。如红白相交,并主两姓同居。"],[7,"梦花卉","梦折花","折者,折也,主有离异之悲,离阴人有碍,谋事最须谨慎。"],[7,"梦花卉","梦采花","采者,采也,主有纳采之庆,大吉。"],[7,"梦花卉","梦偷花","主有邪念。"],[7,"梦花卉","梦风吹花","主离散之兆,不祥。"],[7,"梦花卉","梦送花与人","亦主不祥"],[7,"梦花卉","梦人送花与己","佳兆也"],[7,"梦花卉","梦种花","此为生生之象。梦此主财源旺兴,子嗣昌大。先得女，后生男。"],[7,"梦花卉","梦受花一盒","主功名显贵。"],[7,"梦花卉","梦僧遗花","主得异常之子。"],[7,"梦花卉","梦与花果","主孕男产女之兆。"],[7,"梦竹荻","梦竹","主有归隐之象。"],[7,"梦竹荻","梦种竹","士人梦之,主有两人同得小功名。"],[7,"梦竹荻","梦坐竹林","有身闭心逸之兆。"],[7,"梦竹荻","梦与竹竿","无子嗣者,主得两子。"],[7,"梦竹荻","梦见斑竹","主两地泪零之先兆。"],[7,"梦竹荻","梦入竹林取笋","\uFF08一\uFF09主生男之兆。\uFF08二\uFF09武将梦之,主歼除渠魁。"],[7,"梦竹荻","梦竹\uFF08被雨淋\uFF09","主忧郁堪增。"],[7,"梦竹荻","梦竹被风敲","主生烦恼之象。"],[7,"梦竹荻","梦出笋","孕妇梦之,必主生男。"],[7,"梦竹荻","梦竹生紞","主有子息之象。"],[7,"梦竹荻","梦取笋作羹","主立身行己,顺理无私之兆。"],[7,"梦竹荻","梦以笋点茶","主待人拉物,处事有节之象。"],[7,"梦竹荻","梦折笋","主得财之征。"],[7,"梦竹荻","梦人馈笋","主有病即愈之兆。"],[7,"梦竹荻","梦荻","荻、敌同音,主有草寇窃发,受兵刃之惨,或主失盗。"],[7,"梦诸植物","梦藤","\uFF08一\uFF09君子梦之,主名位升腾。\uFF08二\uFF09老年梦之,主为寿征。\uFF08三\uFF09常人梦之,主家必迁移,病有虚惊。"],[7,"梦诸植物","梦攀援藤","主生才子。"],[7,"梦诸植物","梦浮萍","主群小用事之兆。"],[7,"梦诸植物","梦菖蒲","\uFF08一\uFF09此为昌阳之兆,凡事主称心遂意。\uFF08二\uFF09老妇梦之,主为老鸨之象,真不堪也。"],[7,"梦诸植物","梦折去芭蕉","主家业兴隆之兆。"],[7,"梦诸植物","梦芭蕉","\uFF08一\uFF09土人梦之主贵。\uFF08二\uFF09常人梦之,谋利无望。\uFF08三\uFF09病人主有女祟相侵,禳为吉。"],[8,"梦衣服","梦得蟒衣","凡梦此者,主有大喜庆事。亦主自见神像。"],[8,"梦衣服","梦紫衣","\uFF08一\uFF09妇人梦之,主生贵子。\uFF08二\uFF09富家梦之,主愈富。皆吉征也。"],[8,"梦衣服","梦五彩绣衣","\uFF08一\uFF09士人梦之,主即得成名。\uFF08二\uFF09常人梦之,主有喜庆事,或子贵孙贤。"],[8,"梦衣服","梦着百蝶衣","此为妇人女子之服,未婚主娶妻,无后主纳宠,否则非祥。"],[8,"梦衣服","梦着蓝衣","\uFF08一\uFF09此有青出于蓝之象,贫贱之人梦之,主生俊秀男儿。\uFF08二\uFF09富贵之人梦之,主仍不脱寒酸气。"],[8,"梦衣服","梦着白衣","\uFF08一\uFF09居官者梦此,主官情恬淡。\uFF08二\uFF09居家者梦此,主体度安闲,讼事得直,疾病能痊。\uFF08三\uFF09功名谋望,交易婚均属不利。"],[8,"梦衣服","梦着青衣","青衣为贱者之服,凡梦此者,主诸不吉:贵人遭家难,富家遇官司,商贾交易艰困,婚姻成就无期,出行主逢驿马星,疾病主淹蹇难愈,一切前程,皆不必问。"],[8,"梦衣服","梦冬着夏衣","梦此有寒不得衣,荒凉凄绝之象。主功名难遇交易无望,生涯失利,作事不遂。"],[8,"梦衣服","梦着短衣","此主衣不称体之象。梦之者,谋为必不称心。"],[8,"梦衣服","梦短人着长衣","\uFF08一\uFF09梦此主生涯鼎盛,家业兴旺,有继长增高之征。\uFF08二\uFF09病人梦之,恐牵缠不脱。"],[8,"梦衣服","梦衣服破损","此梦非吉,凡事主有缺失,出门必患重病，居家颇欠安宁,妻妾主有二心,居官定少安逸。"],[8,"梦衣服","梦补衣","\uFF08一\uFF09常人梦之,主善于交友,处事周到。\uFF08二\uFF09妇人梦之,主其夫有过失,或子有远行。"],[8,"梦衣服","梦倒着衣","此为颠倒乱常之象,梦之主行动反常。百无一顺,家业有变,诸病丛生。"],[8,"梦衣服","梦长衣无领","此为事无头绪之象,主求才不得,失物难寻,逃人失踪,出门未归,讼事不胜,患病难医。"],[8,"梦衣服","梦衣被人扯破","此大不吉祥,梦之者,主疾病危险,医儒难救。"],[8,"梦衣服","梦以被当衣着","梦此,有持危扶颠之象,主出入无疾,朋来无咎,利有攸往,如系官司,主有贵人庇护。"],[8,"梦裘类","梦身着双裘","\uFF08一\uFF09梦此者,主有大任至,重务来。主有智谋之士来助。"],[8,"梦裘类","梦服貂裘","梦此主宜出仕,但不利于初,如苏秦是。"],[8,"梦裘类","梦服豹裘","常人梦之,主经营得利,凡百从心,吉兆也。"],[8,"梦裘类","梦千金裘","主为贵重之象。商人梦之,其利倍常,大吉。"],[8,"梦鞋袜","梦倒着鞋","主不能行动之兆,梦此主经营失利,夫妇不和,病情反复,事俱不偶。"],[8,"梦鞋袜","梦脱鞋","女人梦之,致婚姻不谐,与男女相见而后死。"],[8,"梦鞋袜","梦履忽破","此为灾祸重重之象。梦此者,主子孙妻妾有侮,又或童仆有灾。破一履祸在一人,破双履,主有奇祸。"],[8,"梦鞋袜","梦履袜","主有子息之兆,梦履为子,梦袜为女,百不失一。"],[8,"梦鞋袜","梦裹脚","梦此有失足履尾之兆,凡事宜小心谨慎,切勿放纵闲游。"],[8,"梦巾带囊帕","梦失手巾","主灾晦脱离,疾患消除之象,梦之者吉。"],[8,"梦巾带囊帕","梦红汗巾","为大吉之兆,主有喜事临身。"],[8,"梦巾带囊帕","梦百宝带","梦此主贵人扶持,富利缠身。如为商贾,主获奇珍异宝。吉徵也。"],[8,"梦巾带囊帕","梦金带","孕妇梦此,主生贵子。"],[8,"梦巾带囊帕","梦银带","梦此主得大富,招贵子,应长寿,为大利之占。"],[8,"梦巾带囊帕","梦玉带","主为大吉之兆。"],[8,"梦巾带囊帕","梦象牙带","乃位高德重之象,梦此者,主凡事顺利。"],[8,"梦巾带囊帕","梦犀角带","\uFF08一\uFF09常人梦之,主生涯兴盛,诸事可谋。\uFF08二\uFF09孕妇梦之,贵子可望。"],[8,"梦巾带囊帕","梦被囊","\uFF08一\uFF09梦之者,主即有远行。\uFF08二\uFF09行商在外梦之,主保装返棹之象。"],[8,"梦巾带囊帕","梦头扎红帕","主丧服动。梦此者,宜戒争竞,凡事小心,忍耐为贵。"],[8,"梦被褥\uFF08帐惟枕席附\uFF09","梦卧红锦被","梦此主喜临身,满门有庆,事事清吉。"],[8,"梦被褥\uFF08帐惟枕席附\uFF09","梦锦被绣褥","\uFF08一\uFF09贫穷梦之,主有佳好遭逢。\uFF08二\uFF09富梦之,主能结良缘。"],[8,"梦被褥\uFF08帐惟枕席附\uFF09","梦赐褥席","主子孙光大门闾之象。"],[8,"梦被褥\uFF08帐惟枕席附\uFF09","梦亭枕","主二老安宁,人子可高枕无忧之象。"],[8,"梦被褥\uFF08帐惟枕席附\uFF09","梦鸳鸯枕","梦此为诸事吉利之兆,家庭和睦,子孙兴盛,老寿安宁。"],[9,"梦官神宇","梦殿陛宫阙","\uFF08一\uFF09仕官主进取显贵。\uFF08二\uFF09常人主将来荣华富贵。\uFF08三\uFF09妇人女子,主丈夫子婿高贵,亲族孙支茂盛。\uFF08四\uFF09疾病患难主祸去福临,年寿永长。\uFF08五\uFF09僧道尼姑,主天神佛力扶持。"],[9,"梦官神宇","梦坐宫殿中","\uFF08一\uFF09生人梦之,贵人主吉,常人主厄,孕妇主生贵子。\uFF08二\uFF09病人梦之,主离尘凡。\uFF08三\uFF09梦亡人坐宫殿中,主在冥府为神。"],[9,"梦官神宇","梦还殿","主有移借索还之事。"],[9,"梦官神宇","梦宫殿移动","主大事更移转动,分位不宁之兆。"],[9,"梦官神宇","梦宫中光独天","主世乱将治之兆"],[9,"梦官神宇","梦步入深宫","主显贵赫奕之象。"],[9,"梦官神宇","梦坐大宫中","此为上人居高、下人为官之徵。"],[9,"梦官神宇","梦圣庙贤祠","\uFF08一\uFF09主遇圣师,得贤友。\uFF08二\uFF09生女主秀,生男主贵。吉利之至。"],[9,"梦官神宇","梦登塔","主本身有荣显之兆。"],[9,"梦第宅","梦人求客舍","主家宅不宁,已故者主求祠祀。"],[9,"梦第宅","梦己求宅舍","吉兆也。"],[9,"梦第宅","梦造物与人","主子孙显贵之兆。"],[9,"梦第宅","梦建造大屋","主功成名就,兴盛昌泰。"],[9,"梦第宅","梦迁居","主事之变更之象。"],[9,"梦第宅","梦家中起造修葺","主兴隆发达之兆。"],[9,"梦第宅","柱欹斜","主不祥之兆。"],[9,"梦第宅","梦柱倾折","主本身有死亡之征。"],[9,"梦第宅","梦外人坐堂中","主他日人将处此代我,非吉兆也,宜预防之。"],[9,"梦第宅","梦堂倾陷","\uFF08一\uFF09常人梦此,主病忠危迫。\uFF08二\uFF09富贵梦此,主家败身灾。\uFF08三\uFF09女人梦此,主夫身有难。\uFF08四\uFF09仆役梦此,主家有灾危。"],[9,"梦第宅","梦堂下开店","主胸有贪私,务速趋吉避凶。"],[9,"梦第宅","梦堂高屋广","主去病改过之象。"],[9,"梦第宅","梦身出户外","主大事不祥。"],[9,"梦第宅","梦众人屋下笑哭","主凶事不宁。"],[9,"梦第宅","梦众人行坐屋两旁","主富贵荣华之象。"],[9,"梦第宅","梦外人欢呼","主有好事将至。"],[9,"梦第宅","梦划楝朱门","梦此主有恩荣,百事俱宜,大吉大利。"],[9,"梦第宅","梦闲居安坐","主身体康宁,寿算永长。"],[9,"梦第宅","梦生存回家","主久别聚会之兆。"],[9,"梦第宅","梦生存去家","主骨肉分离之象"],[9,"梦第宅","梦家宅废毁残坏","主大凶。"],[9,"梦第宅","梦身自墙隙出","主客死异乡之兆。"],[9,"梦第宅","梦门窗大开","主吉祥之兆。"],[9,"梦第宅","梦门户中见人物","须随事推详,休咎便可知矣。"],[9,"梦第宅","梦户牖毁坏暗闭","主灾祸临身。"],[9,"梦第宅","梦窗牖见月影花光","主有喜事至。"],[9,"梦第宅","梦草结窗前","士子梦之,主文章上达之兆。"],[9,"梦第宅","梦庭中仰见三光","吉兆也。"],[9,"梦第宅","梦庭中见烟云","主有灾殃至。"],[9,"梦第宅","梦泉涌","主获财利之象。"],[9,"梦第宅","梦身坐井中","梦此者,主狱讼不胜,征战被围,功名不遂,营谋不利,幼小之人,主定夭丧。"],[9,"梦第宅","梦伏藏井内","主有牢狱之苦。"],[9,"梦第宅","梦醉入井中","主有讼事。"],[9,"梦第宅","梦入井得出","主有他人前来护助。"],[9,"梦第宅","梦身坠井中","主家内有水火之灾。"],[9,"梦第宅","梦自井中跳出","主有远行,为大吉之象。"],[9,"梦第宅","梦仓库","充足者,主年丰民足。虚耗者,主年荒国乱。"],[9,"梦第宅","梦仓廪充盈","主下人吉,上人凶。"],[9,"梦第宅","梦府库充勇","主上人吉,下人凶。"],[9,"梦第宅","梦坑厕","\uFF08一\uFF09君子梦之,主事不谐,身陷囹圄,失财大凶。\uFF08二\uFF09小人梦之,主能得财。"],[9,"梦第宅","梦在厕圊中","\uFF08一\uFF09病人梦之,主身体康健。\uFF08二\uFF09梦亡人在厕圊中,主要冥司受苦,速宜追荐超渡。"],[9,"梦第宅","梦入厕圊身污得出","主得大富之兆。"],[9,"梦第宅","梦陷入深坑","主有大灾。死亡即至。"],[9,"梦第宅","梦见马坊","主通达之象。"],[9,"梦第宅","梦修造马坊","主得富贵。"],[9,"梦第宅","梦厩中无马","主作事不成。"],[9,"梦第宅","梦厩中马舞","主火灾发现之象。"],[9,"梦第宅","梦马坊破坏","主家中人有灾。"],[9,"梦第宅","梦厩中马嘶","主有口舌是非。"],[9,"梦第宅","梦马入厩","主有音信至。"],[9,"梦第宅","梦马出厩","主远行之兆。"],[9,"梦亭台楼阁","梦侍康亭","梦此主生贵女。"],[9,"梦亭台楼阁","梦亭轩","主安宁停住之象。"],[9,"梦亭台楼阁","梦亭轩高耸","主富贵永康之兆。"],[9,"梦亭台楼阁","梦亭坏","主恩泽有份。"],[9,"梦亭台楼阁","梦见灵台","梦此主得良友相助之益。"],[9,"梦亭台楼阁","梦登台远眺","梦此主喜庆之兆。"],[9,"梦亭台楼阁","梦白玉楼","士子梦此,主不吉利,有短命之兆。"],[9,"梦亭台楼阁","梦彩楼高阁","主气旺精足之象。"],[9,"梦亭台楼阁","梦楼台倾陷","主有疾病灾晦。"],[9,"梦亭台楼阁","梦登阁","文人及仕宦梦之,皆大显达。"],[9,"梦亭台楼阁","梦瓦石毁圯","主不祥之兆。"],[9,"梦田园坟墓","梦田旱","此为仰望云雨之兆,农人梦之,主来年五谷丰登。"],[9,"梦田园坟墓","梦在田边饮酒","\uFF08一\uFF09主酉日有雨,欢呼大乐。\uFF08二\uFF09富家梦之,主有沟渠闭塞之事。\uFF08三\uFF09常人梦之,主於酉年日月有哭泣事。"],[9,"梦田园坟墓","梦自己种田","\uFF08一\uFF09常人梦之,主有出行之兆,又主酒食丰盛,妻妾怀孕,家业充足。\uFF08二\uFF09商贾梦之,主财帛可得,亲友往来。"],[9,"梦田园坟墓","梦田中大水","春秋梦之,凡事主不求自至,吉祥顺遂。冬夏梦之不佳。"],[9,"梦田园坟墓","梦见人种田","文人梦此,主有禄位来临。余人梦之亦佳。"],[9,"梦田园坟墓","梦游园林","仕宦梦之,主终於任所之兆。"],[9,"梦田园坟墓","梦园中亭台一新","此为富贵之象。梦之者,主易旧更新,改换门户。"],[9,"梦田园坟墓","梦身入果园","此为利於闺阃之兆,女人梦之,主得胎孕。常人梦之,主得大财。"],[9,"梦田园坟墓","梦在园中秋千","\uFF08一\uFF09女人梦之,主有丰足喜乐之象。\uFF08二\uFF09男子梦之,主高而防危、虚而无实,动而不静,险兆也,非速禳解不可。"],[9,"梦田园坟墓","梦见新坟","梦此主凡百忧虞之事,均能消散。"],[9,"梦田园坟墓","梦见坟中人起","\uFF08一\uFF09主得遇见文人之兆。\uFF08二\uFF09主进取有望,家业再造。\uFF08三\uFF09防有小人偷窃之患。"],[9,"梦田园坟墓","梦坟墓高大","梦此者,主家业丰盛,子嗣贤秀,大吉之占也。"],[9,"梦田园坟墓","梦祭扫坟墓","\uFF08一\uFF09士人主文章日进。\uFF08二\uFF09女人主夫婿远归。\uFF08三\uFF09常人主孝行宜修。均皆清吉。"]];

